import { CURRENT_FLOW_SCHEMA_REVISION } from "../../lib/flow-schema-revision.js";
/** Explicit human display for one closed canonical Flow artifact view. */

import { Command } from "../../lib/command.js";
import { Envelope } from "../../lib/flow-envelope.js";
import { FlowSpecId } from "../../lib/flow-spec-id.js";
import { FLOW_ARTIFACT_VIEW_REGISTRY } from "./artifact-view-registry.js";
import { ArtifactViewService } from "./artifact-view-service.js";
import {
  AcceptanceArtifactSummaryContract,
  ArtifactViewSummaryError,
  ArtifactViewSummaryService,
  SpecArtifactSummaryContract,
} from "./artifact-view-summary.js";
import { FlowCommand } from "./base-command.js";

const MODES = new Set(["full", "summary"]);
const ACTIVE_TARGET_GUARD_FIELDS = Object.freeze([
  "expectBinding", "expectIssue", "expectSpec", "expectRunId", "expectNoIssue",
]);

function nonEmptyText(value, field) {
  if (typeof value !== "string" || value.trim() === "") {
    throw new ArtifactViewRequestError(`${field} is required`);
  }
  return value.trim();
}

function explicitVersion(value) {
  const raw = nonEmptyText(value, "--version");
  if (!/^[1-9][0-9]*$/.test(raw)) {
    throw new ArtifactViewRequestError("--version must be a positive integer");
  }
  const version = Number(raw);
  if (!Number.isSafeInteger(version)) {
    throw new ArtifactViewRequestError("--version must be a positive safe integer");
  }
  return version;
}

function hasExplicitVersionSelector(input = {}) {
  return (input.specId !== null && input.specId !== undefined)
    || (input.version !== null && input.version !== undefined);
}

function activeGuardNames(input = {}) {
  return ACTIVE_TARGET_GUARD_FIELDS.filter((field) => input[field] !== null && input[field] !== undefined && input[field] !== false);
}

/** Safe input-boundary failure that becomes a standard Flow envelope. */
export class ArtifactViewRequestError extends Error {
  constructor(message) {
    super(message);
    this.name = "ArtifactViewRequestError";
    this.code = "ARGS_ERROR";
  }
}

/** Immutable CLI request; it never accepts an inferred historical target. */
export class ArtifactViewRequest {
  constructor(input = {}) {
    if (input === null || typeof input !== "object" || Array.isArray(input)) {
      throw new ArtifactViewRequestError("artifact view input must be an object");
    }
    const logicalKey = nonEmptyText(input.logicalKey, "artifact logicalKey");
    try {
      this.logicalKey = FLOW_ARTIFACT_VIEW_REGISTRY.require(logicalKey).logicalKey;
    } catch {
      throw new ArtifactViewRequestError(`unsupported artifact logicalKey: ${logicalKey}`);
    }
    this.mode = nonEmptyText(input.mode, "--mode");
    if (!MODES.has(this.mode)) {
      throw new ArtifactViewRequestError("--mode must be full or summary");
    }
    const hasSpecId = input.specId !== null && input.specId !== undefined;
    const hasVersion = input.version !== null && input.version !== undefined;
    if (hasSpecId !== hasVersion) {
      throw new ArtifactViewRequestError("--spec-id and --version must be provided together");
    }
    this.historical = hasSpecId;
    if (this.historical) {
      try {
        this.specId = FlowSpecId.from(nonEmptyText(input.specId, "--spec-id")).toString();
      } catch {
        throw new ArtifactViewRequestError("--spec-id must be a literal specId");
      }
      this.version = explicitVersion(input.version);
      const guards = activeGuardNames(input);
      if (guards.length > 0) {
        throw new ArtifactViewRequestError(
          `completed Version views cannot use active Flow guards: ${guards.map((field) => `--${field.replace(/[A-Z]/g, (letter) => `-${letter.toLowerCase()}`)}`).join(", ")}`,
        );
      }
    } else {
      this.specId = null;
      this.version = null;
    }
    Object.freeze(this);
  }

  static hasExplicitVersionSelector(input = {}) {
    return hasExplicitVersionSelector(input);
  }
}

function summaryContractFor(request, localizer) {
  if (request.logicalKey === "spec.record") {
    return new SpecArtifactSummaryContract({
      title: localizer.message("titleSpec"),
      headings: {
        purpose: localizer.message("purpose"),
        scope: localizer.message("scope"),
        constraints: localizer.message("constraints"),
        openQuestions: localizer.message("openQuestions"),
        requirements: localizer.message("requirements"),
        tasks: localizer.message("tasks"),
      },
    });
  }
  return new AcceptanceArtifactSummaryContract({
    title: localizer.message("titleAcceptance"),
    headings: {
      requirements: localizer.message("requirementJudgments"),
      mechanicalBlockers: localizer.message("mechanicalBlockers"),
      hardBlockers: localizer.message("hardBlockers"),
      deferredFindings: localizer.message("deferredFindings"),
      remainingRisks: localizer.message("remainingRisks"),
    },
  });
}

function failureFor(error, mode) {
  if (error instanceof ArtifactViewRequestError || error instanceof ArtifactViewSummaryError) {
    return Envelope.fail("get", "artifact", error.code, error.message);
  }
  const code = typeof error?.code === "string" && error.code !== ""
    ? error.code
    : (mode === "summary" ? "ARTIFACT_VIEW_SUMMARY_FAILED" : "ARTIFACT_VIEW_FULL_FAILED");
  return Envelope.fail("get", "artifact", code, error?.message || String(error));
}

function activeContextReadFailure(error) {
  // Active target resolution reconstructs the canonical Flow state before the
  // view service can read the requested artifact.  A corrupt attempt history
  // at that boundary is still a canonical artifact read failure, never an AI
  // summary failure.  Keep its original error as the cause for diagnostics
  // while presenting the closed public view error taxonomy.
  if (error?.code === "ARTIFACT_VIEW_READ_FAILED") return error;
  const wrapped = new Error(error?.message || String(error), { cause: error });
  wrapped.name = "ArtifactViewActiveContextReadError";
  wrapped.code = "ARTIFACT_VIEW_READ_FAILED";
  return wrapped;
}

function appendCacheWarning(envelope, warning) {
  if (warning !== null && warning !== undefined) {
    envelope.addWarning(warning.code || "ARTIFACT_VIEW_CACHE_NOT_SAVED", warning.message || String(warning));
  }
}

/** `flow get artifact` with an intentionally isolated completed-Version path. */
export default class GetArtifactCommand extends FlowCommand {
  constructor() {
    // Read resolution permits an identity match before the binding authority
    // check below. That turns a stale same-id binding into the public
    // ACTIVE_FLOW_MISMATCH boundary instead of treating the active flow as
    // absent; targetGuard then validates the complete captured authority
    // before the reader, cache, or summary agent can run.
    super({
      requiresFlow: false,
      explicitTargetResolution: true,
      mismatchTargetResolution: true,
      targetGuard: true,
    });
  }

  async run(container, input = {}) {
    // FlowCommand.run() resolves ambient Flow authority even for optional
    // commands. Historical selectors must not do that: their exact pair is
    // independently authoritative and active guards are rejected above.
    if (ArtifactViewRequest.hasExplicitVersionSelector(input)) {
      return Command.prototype.run.call(this, container, input);
    }
    try {
      return await super.run(container, { ...input, _artifactViewRequestInput: input });
    } catch (error) {
      return failureFor(activeContextReadFailure(error), input.mode);
    }
  }

  async execute(ctx) {
    const input = ctx._artifactViewRequestInput || ctx;
    let request;
    try {
      request = new ArtifactViewRequest(input);
      if (!request.historical && !ctx.flowState) {
        return Envelope.fail("get", "artifact", "NO_ACTIVE_FLOW", "an active canonical Flow is required when --spec-id/--version are omitted");
      }
      if (!request.historical && (ctx.flowState?.schemaRevision !== CURRENT_FLOW_SCHEMA_REVISION || typeof ctx.flowState.specId !== "string")) {
        return Envelope.fail("get", "artifact", "CANONICAL_FLOW_REQUIRED", "active Flow must be backed by the canonical Version Store");
      }

      const flowManager = request.historical
        ? this.container.get("flowManager")
        : ctx.flowManager;
      const root = request.historical
        ? this.container.get("mainRoot")
        : ctx.root;
      const config = this.container.get("config") || {};
      const viewService = new ArtifactViewService({ config, root, flowManager });
      const full = viewService.full({
        logicalKey: request.logicalKey,
        ...(request.historical
          ? { specId: request.specId, version: request.version }
          : { activeState: ctx.flowState }),
      });

      let markdown = full.markdown;
      let summaryWarning = null;
      if (request.mode === "summary") {
        const localizer = viewService.renderer.localizer;
        const summary = await new ArtifactViewSummaryService({
          agent: this.container.get("agent"),
          cache: full.cacheStore,
          lang: full.fullView.language,
          i18nRevision: full.fullView.i18nRevision,
          cacheWarningMessage: localizer.message("cacheNotSaved"),
        }).summarize({
          fullView: full.fullView,
          contract: summaryContractFor(request, localizer),
        });
        markdown = summary.markdown;
        summaryWarning = summary.cache.warning;
      }

      const envelope = Envelope.ok("get", "artifact", { markdown });
      appendCacheWarning(envelope, full.cacheWarning);
      appendCacheWarning(envelope, summaryWarning);
      return envelope;
    } catch (error) {
      return failureFor(error, request?.mode || input.mode);
    }
  }
}

export { summaryContractFor };

/**
 * src/flow/lib/get-check.js
 *
 * Check prerequisites for a phase.
 * Prerequisites are derived from the definition hierarchy.
 */

import { isGhAvailable, runGit } from "../../lib/git-helpers.js";
import { VALID_CHECK_TARGETS } from "../../lib/constants.js";
import { FlowCommand } from "./base-command.js";
import { deriveFlowPrereqs } from "../definition.js";
import { flattenSteps } from "./step-tree.js";

function checkStepPrereqs(state, targetId) {
  const required = deriveFlowPrereqs(targetId);
  const flat = Array.isArray(state.steps) && state.steps.some((s) => s.children)
    ? flattenSteps(state.steps)
    : (state.steps || []);
  const checks = [];
  for (const id of required) {
    const step = flat.find((s) => s.id === id);
    const pass = step && (step.status === "done" || step.status === "skipped");
    checks.push({ id, pass, message: pass ? `${id}: ${step.status}` : `${id}: not completed` });
  }
  const pass = checks.every((c) => c.pass);
  const summary = pass ? "all prerequisites met" : `missing: ${checks.filter((c) => !c.pass).map((c) => c.id).join(", ")}`;
  return { pass, summary, checks };
}

function checkDirty(root) {
  const res = runGit(["status", "--short"], { cwd: root });
  if (!res.ok) {
    return { pass: false, summary: "git status failed", checks: [{ id: "dirty", pass: false, message: res.stderr }] };
  }
  const lines = res.stdout.trim().split("\n").filter(Boolean);
  const pass = lines.length === 0;
  return {
    pass,
    summary: pass ? "working tree clean" : `${lines.length} uncommitted change(s)`,
    checks: [{ id: "dirty", pass, message: pass ? "clean" : lines.join(", ") }],
  };
}

function checkGh() {
  const available = isGhAvailable();
  return {
    pass: available,
    summary: available ? "gh available" : "gh command not found",
    checks: [{ id: "gh", pass: available, message: available ? "available" : "not available" }],
  };
}

export default class GetCheckCommand extends FlowCommand {
  constructor() {
    super({ requiresFlow: false });
  }

  execute(ctx) {
    const { root } = ctx;
    const executionRoot = ctx.executionRoot || root;
    const target = ctx.target;

    if (!target) {
      throw new Error(`target required. valid: ${VALID_CHECK_TARGETS.join(", ")}`);
    }

    if (!VALID_CHECK_TARGETS.includes(target)) {
      throw new Error(`unknown target '${target}'. valid: ${VALID_CHECK_TARGETS.join(", ")}`);
    }

    if (target === "dirty") {
      return checkDirty(executionRoot);
    }

    if (target === "gh") {
      return checkGh();
    }

    const state = ctx.flowState;
    if (!state) {
      return { pass: false, summary: "no active flow", checks: [] };
    }

    return checkStepPrereqs(state, target === "impl" ? "implement" : target);
  }
}

/**
 * src/flow/lib/get-context.js
 *
 * Retrieve analysis context in various modes:
 * - File mode (ctx.filePath): return file content
 * - Search mode (ctx.searchQuery): keyword search in analysis entries
 * - List mode (default): return filtered analysis entries
 *
 * ctx.filePath    — file path relative to root (file mode)
 * ctx.searchQuery — search query string (search mode)
 */

import fs from "fs";
import path from "path";
import { createHash } from "node:crypto";
import { managedOutputDir, loadConfig } from "../../lib/config.js";
import { FlowCommand } from "./base-command.js";
import { iterateAnalysisCategories } from "../../docs/lib/analysis-entry.js";
import { container } from "../../lib/container.js";
import { PromptBuilder } from "../../lib/prompt-builder.js";
import {
  AtomicPromptElement, PromptInputBuilder, PromptRequestEnvelope, PromptRequestLimit,
  PromptBatchPlan, PromptBatchExecutor, PromptBatchReducer, PromptResponseCoverageInvalidFailure,
} from "../../lib/prompt-batching.js";

const EXCLUDE_FIELDS = new Set(["hash", "mtime", "lines", "id", "enrich", "detail"]);

function toSearchResult(e) {
  return {
    file: e.file,
    summary: e.summary || null,
    keywords: e.keywords,
    chapter: e.chapter || null,
    role: e.role || null,
  };
}

/**
 * Search analysis entries by keyword matching against the keywords array.
 * @param {Object[]} entries - Analysis entries (with keywords, summary, detail, etc.)
 * @param {string} query - Search query string
 * @returns {Object[]} Matched entries with file, summary, detail, keywords, chapter, role
 */
function searchEntries(entries, query) {
  const q = query.toLowerCase();
  return entries
    .filter((e) => {
      if (!Array.isArray(e.keywords)) return false;
      return e.keywords.some((kw) => String(kw).toLowerCase().includes(q));
    })
    .map((e) => toSearchResult(e));
}

/**
 * Collect all unique keywords from analysis.json entries.
 * @param {Object} analysis - Parsed analysis.json
 * @returns {string[]} Unique keywords array
 */
function collectAllKeywords(analysis, limit = 0) {
  const freq = new Map();
  for (const [, catData] of iterateAnalysisCategories(analysis)) {
    for (const e of catData.entries) {
      if (!Array.isArray(e.keywords)) continue;
      for (const kw of e.keywords) {
        const s = String(kw);
        freq.set(s, (freq.get(s) || 0) + 1);
      }
    }
  }
  // Sort by frequency descending, then alphabetically for stability
  const sorted = [...freq.entries()]
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .map(([kw]) => kw);
  return limit > 0 ? sorted.slice(0, limit) : sorted;
}

/**
 * Build a prompt for AI keyword selection.
 * @param {string[]} keywords - Available keywords from analysis
 * @param {string} query - User's natural language query
 * @returns {string} Prompt text
 */
const KEYWORD_SELECTION_SCHEMA = {
  type: "object",
  properties: {
    keywords: {
      type: "array",
      items: { type: "string" },
    },
  },
  required: ["keywords"],
  additionalProperties: false,
};

const KEYWORD_SELECTION_FMT_FALLBACK = 'Return ONLY a JSON object with a keywords array. No explanation, no markdown fences.\nExample output: {"keywords":["auth","認証","session","login"]}';

function buildKeywordSelectionPrompt(keywords, query) {
  const pb = _buildKeywordSelectionPb(keywords, query);
  const built = pb.build();
  const parts = [];
  if (built.systemPrompt) parts.push(built.systemPrompt);
  if (built.fmtFallback) parts.push(built.fmtFallback);
  if (built.userPrompt) parts.push(built.userPrompt);
  return parts.join("\n\n");
}

function _buildKeywordSelectionPb(keywords, query) {
  const pb = new PromptBuilder();
  pb.setRole("You are a keyword selector. Given a query and a list of available keywords, select the keywords that are relevant to the query.");

  const rules = [
    "- Select 5-20 keywords that are most relevant to the query.",
    "- Include both direct matches and semantically related keywords.",
  ].join("\n");
  pb.setRules(rules);
  pb.setJsonSchema(KEYWORD_SELECTION_SCHEMA);
  pb.setFmtFallback(KEYWORD_SELECTION_FMT_FALLBACK);

  pb.addUserPrompt("## Query", query);
  pb.addUserPrompt("## Available keywords", keywords.join(", "));

  return pb;
}

class KeywordSelectionEnvelope extends PromptRequestEnvelope {
  constructor(query) {
    super();
    this.query = query;
  }

  build(elements) {
    return _buildKeywordSelectionPb(elements.map((element) => element.toPromptText()), this.query).build();
  }
}

class SelectedKeywordResult {
  constructor(raw, batch) {
    const cleaned = raw.trim().replace(/^```(?:json)?\s*\n?/i, "").replace(/\n?```\s*$/i, "");
    const parsed = JSON.parse(cleaned);
    const selected = parsed.keywords;
    const allowed = new Set(batch.elements.map((element) => element.toPromptText()));
    if (!Array.isArray(selected) || selected.some((keyword) => typeof keyword !== "string" || !allowed.has(keyword))) {
      throw new PromptResponseCoverageInvalidFailure("Keyword selection contains an unknown keyword");
    }
    this.keywords = Object.freeze([...new Set(selected)]);
    Object.freeze(this);
  }
}

class SelectedKeywordReducer extends PromptBatchReducer {
  reduce(completions) {
    return [...new Set(completions.flatMap((completion) => completion.response.keywords))];
  }
}

/**
 * Fallback search: split query by spaces, OR-match against keywords.
 * @param {Object[]} entries - Analysis entries
 * @param {string} query - Space-separated keywords
 * @returns {Object[]} Matched entries (deduplicated)
 */
function fallbackSearch(entries, query) {
  const terms = query.split(/\s+/).filter(Boolean).map((t) => t.toLowerCase());
  if (terms.length === 0) return [];
  const seen = new Set();
  const results = [];
  for (const e of entries) {
    if (!Array.isArray(e.keywords)) continue;
    const match = terms.some((t) =>
      e.keywords.some((kw) => String(kw).toLowerCase().includes(t))
    );
    if (match && !seen.has(e.file)) {
      seen.add(e.file);
      results.push(toSearchResult(e));
    }
  }
  return results;
}

const NGRAM_THRESHOLD = 0.6;
const NGRAM_MIN_RESULTS = 5;
const NGRAM_MAX_RESULTS = 30;
const HUB_CONNECTION_THRESHOLD = 20;

function toBigrams(text) {
  const s = text.toLowerCase();
  if (s.length < 2) return [];
  const bigrams = [];
  for (let i = 0; i < s.length - 1; i++) {
    bigrams.push(s.slice(i, i + 2));
  }
  return bigrams;
}

function bigramSimilarity(a, b) {
  if (a.length === 0 || b.length === 0) return 0.0;
  const setA = new Set(a);
  const setB = new Set(b);
  let intersection = 0;
  for (const bg of setA) {
    if (setB.has(bg)) intersection++;
  }
  return (2 * intersection) / (setA.size + setB.size);
}

function ngramSearch(allEntries, query) {
  const words = query.split(/\s+/).filter(Boolean);
  if (words.length === 0) return [];

  const wordBigrams = words.map((w) => toBigrams(w));
  if (wordBigrams.every((bg) => bg.length === 0)) return [];

  let maxImports = 0;
  let maxMethods = 0;
  for (const e of allEntries) {
    const ic = Array.isArray(e.imports) ? e.imports.length : 0;
    const mc = Array.isArray(e.methods) ? e.methods.length : 0;
    if (ic > maxImports) maxImports = ic;
    if (mc > maxMethods) maxMethods = mc;
  }

  const scored = [];
  for (const e of allEntries) {
    if (!Array.isArray(e.keywords) || e.keywords.length === 0) continue;

    let matchCount = 0;
    let totalSim = 0;
    for (const wbg of wordBigrams) {
      if (wbg.length === 0) continue;
      let bestSim = 0;
      for (const kw of e.keywords) {
        const sim = bigramSimilarity(wbg, toBigrams(String(kw)));
        if (sim > bestSim) bestSim = sim;
      }
      if (bestSim >= NGRAM_THRESHOLD) {
        matchCount++;
        totalSim += bestSim;
      }
    }

    if (matchCount === 0) continue;

    const ic = Array.isArray(e.imports) ? e.imports.length : 0;
    const mc = Array.isArray(e.methods) ? e.methods.length : 0;
    const importBonus = maxImports > 0 ? (ic / maxImports) * 0.5 : 0;
    const methodBonus = maxMethods > 0 ? (mc / maxMethods) * 0.3 : 0;
    const score = totalSim + matchCount + importBonus + methodBonus;

    scored.push({ entry: e, score, matchCount });
  }

  const multiMatch = scored.filter((s) => s.matchCount >= 2);
  const singleMatch = scored.filter((s) => s.matchCount === 1);
  singleMatch.sort((a, b) => b.score - a.score);

  let results = [...multiMatch];
  for (const s of singleMatch) {
    if (results.length >= NGRAM_MAX_RESULTS) break;
    results.push(s);
  }

  if (results.length < NGRAM_MIN_RESULTS) {
    for (const s of singleMatch) {
      if (results.includes(s)) continue;
      results.push(s);
      if (results.length >= NGRAM_MIN_RESULTS) break;
    }
  }

  results = results.slice(0, NGRAM_MAX_RESULTS);
  results.sort((a, b) => b.score - a.score);

  return results.map(({ entry, score }) => {
    const sr = toSearchResult(entry);
    sr.score = score;
    return sr;
  });
}

/**
 * AI-powered keyword selection + static match search.
 * Falls back to space-split OR search if agent is unavailable.
 * @param {Object[]} allEntries - All analysis entries
 * @param {Object} analysis - Full analysis object (for keyword collection)
 * @param {string} query - Natural language query
 * @param {string} root - Project root path
 * @returns {Object[]} Matched entries
 */
async function aiSearch(allEntries, analysis, query, _root) {
  const allKeywords = collectAllKeywords(analysis);
  if (allKeywords.length === 0) return fallbackSearch(allEntries, query);

  const agent = container.get("agent");
  if (!agent.resolve("flow.context.search")) return fallbackSearch(allEntries, query);

  let selectedKeywords;
  try {
    const limit = new PromptRequestLimit({ maxCharacters: agent.promptCharacterLimit ?? 120_000 });
    const envelope = new KeywordSelectionEnvelope(query);
    const builder = new PromptInputBuilder({ envelope, limit });
    allKeywords.forEach((keyword, sequence) => builder.add(new AtomicPromptElement({
      id: `keyword:${sequence}`, sequence, text: keyword,
      sourceRevision: createHash("sha256").update(keyword).digest("hex"),
    })));
    const plan = PromptBatchPlan.create({ collection: builder.build(), envelope, limit });
    selectedKeywords = await new PromptBatchExecutor().execute({
      plan,
      callAgent: (built, _batch, _retryIndex, _attempt, providerCallAdmission) => agent.call(built.userPrompt, {
        ...built, commandId: "flow.context.search", providerCallAdmission,
      }),
      projectInvocation: typeof agent.projectInvocation === "function"
        ? (built) => agent.projectInvocation(built.userPrompt, { ...built, commandId: "flow.context.search" })
        : undefined,
      responseContract: { parse: (raw, batch) => new SelectedKeywordResult(raw, batch) },
      reducer: new SelectedKeywordReducer(),
    });
  } catch (err) {
    process.stderr.write(`[sennel] context aiSearch failed: ${err.message}\n`);
    return fallbackSearch(allEntries, query);
  }

  // Use selected keywords for OR search
  if (selectedKeywords.length === 0) return fallbackSearch(allEntries, query);

  const terms = selectedKeywords.map((k) => String(k).toLowerCase());
  const seen = new Set();
  const results = [];
  for (const e of allEntries) {
    if (!Array.isArray(e.keywords)) continue;
    const match = terms.some((t) =>
      e.keywords.some((kw) => String(kw).toLowerCase().includes(t))
    );
    if (match && !seen.has(e.file)) {
      seen.add(e.file);
      results.push(toSearchResult(e));
    }
  }
  // If AI-selected keywords matched nothing, fall back to text search
  if (results.length === 0) return fallbackSearch(allEntries, query);
  return results;
}

/**
 * Dispatch search based on configured mode with fallback chain.
 * - ngram mode: ngramSearch → fallbackSearch → aiSearch
 * - ai mode: aiSearch → fallbackSearch (legacy behavior)
 * @param {Object[]} allEntries - All analysis entries
 * @param {Object} analysis - Full analysis object
 * @param {string} query - Search query
 * @param {string} root - Project root path
 * @param {string} mode - Search mode ("ngram" or "ai")
 * @returns {Object[]} Matched entries
 */
function isHub(entry) {
  const ic = Array.isArray(entry.imports) ? entry.imports.length : 0;
  const uc = Array.isArray(entry.usedBy) ? entry.usedBy.length : 0;
  return (ic + uc) >= HUB_CONNECTION_THRESHOLD;
}

function _postProcess(results, allEntries, options) {
  const seen = new Set(results.map((r) => r.file));
  const scoreMap = new Map();
  for (const r of results) {
    scoreMap.set(r.file, r.score || 0);
  }

  if (Array.isArray(options.scopePaths)) {
    const entryMap = new Map(allEntries.map((e) => [e.file, e]));
    let maxImports = 0;
    let maxMethods = 0;
    for (const e of allEntries) {
      const ic = Array.isArray(e.imports) ? e.imports.length : 0;
      const mc = Array.isArray(e.methods) ? e.methods.length : 0;
      if (ic > maxImports) maxImports = ic;
      if (mc > maxMethods) maxMethods = mc;
    }
    for (const sp of options.scopePaths) {
      if (seen.has(sp)) continue;
      const entry = entryMap.get(sp);
      if (!entry) continue;
      const sr = toSearchResult(entry);
      const ic = Array.isArray(entry.imports) ? entry.imports.length : 0;
      const mc = Array.isArray(entry.methods) ? entry.methods.length : 0;
      const importBonus = maxImports > 0 ? (ic / maxImports) * 0.5 : 0;
      const methodBonus = maxMethods > 0 ? (mc / maxMethods) * 0.3 : 0;
      sr.score = importBonus + methodBonus;
      results.push(sr);
      seen.add(sp);
      scoreMap.set(sp, sr.score);
    }
  }

  if (options.expandImports) {
    const entryMap = new Map(allEntries.map((e) => [e.file, e]));
    const directMatchFiles = new Set(seen);
    for (const file of directMatchFiles) {
      const entry = entryMap.get(file);
      if (!entry || !Array.isArray(entry.imports)) continue;
      const parentScore = scoreMap.get(file) || 0;
      for (const imp of entry.imports) {
        if (seen.has(imp)) continue;
        const impEntry = entryMap.get(imp);
        if (!impEntry) continue;
        if (isHub(impEntry)) continue;
        const sr = toSearchResult(impEntry);
        sr.score = parentScore * 0.5;
        results.push(sr);
        seen.add(imp);
        scoreMap.set(imp, sr.score);
      }
    }
  }

  results.sort((a, b) => (b.score || 0) - (a.score || 0));
  return results;
}

function contextSearch(allEntries, analysis, query, root, mode = "ngram", options = {}) {
  if (mode === "ai") {
    return aiSearch(allEntries, analysis, query, root);
  }

  let results = ngramSearch(allEntries, query);
  if (results.length === 0) {
    results = fallbackSearch(allEntries, query);
  }

  const processed = _postProcess(results, allEntries, options);

  if (processed.length === 0) {
    return aiSearch(allEntries, analysis, query, root);
  }

  return processed;
}

function filterEntry(entry) {
  const filtered = {};
  for (const [k, v] of Object.entries(entry)) {
    if (EXCLUDE_FIELDS.has(k)) continue;
    filtered[k] = v;
  }
  if (!filtered.summary) {
    filtered.needsSource = true;
  }
  return filtered;
}

/**
 * Load and flatten all analysis entries from analysis.json.
 * @param {string} root - Project root path
 * @returns {{ analysis: Object, entries: Object[] }}
 */
function loadAnalysisEntries(root) {
  const outputDir = managedOutputDir(root);
  const analysisPath = path.join(outputDir, "analysis.json");

  if (!fs.existsSync(analysisPath)) {
    throw new Error("analysis.json not found. Run: sennel docs scan");
  }

  let analysis;
  try {
    analysis = JSON.parse(fs.readFileSync(analysisPath, "utf8"));
  } catch (e) {
    throw new Error(`Failed to parse analysis.json: ${e.message}`);
  }

  const entries = [];
  for (const [, catData] of iterateAnalysisCategories(analysis)) {
    for (const entry of catData.entries) {
      entries.push(entry);
    }
  }

  return { analysis, entries };
}

export default class GetContextCommand extends FlowCommand {
  async execute(ctx) {
    const { root } = ctx;
    const filePath = ctx.filePath || ctx.path || null;
    const searchQuery = ctx.searchQuery || ctx.search || null;

    // File mode
    if (filePath) {
      const absPath = path.resolve(root, filePath);
      if (!fs.existsSync(absPath)) {
        throw new Error(`file not found: ${filePath}`);
      }

      const isDocsPath = filePath.startsWith("docs/") || filePath.startsWith("docs\\");
      const content = fs.readFileSync(absPath, "utf8");

      return {
        path: filePath,
        type: isDocsPath ? "docs" : "src",
        content,
      };
    }

    // Search mode
    if (searchQuery) {
      const { analysis, entries: allEntries } = loadAnalysisEntries(root);

      let config;
      try { config = loadConfig(root); } catch (_e) { config = {}; }
      const searchMode = config?.flow?.commands?.context?.search?.mode ?? "ngram";
      const results = await contextSearch(allEntries, analysis, searchQuery, root, searchMode);

      return {
        total: results.length,
        entries: results,
      };
    }

    // List mode
    const { entries: allEntries } = loadAnalysisEntries(root);
    const filtered = allEntries.map((entry) => filterEntry(entry));

    return {
      total: filtered.length,
      entries: filtered,
    };
  }
}

export { filterEntry, searchEntries, collectAllKeywords, buildKeywordSelectionPrompt, fallbackSearch, toBigrams, bigramSimilarity, ngramSearch, loadAnalysisEntries, contextSearch };

/**
 * src/flow/lib/get-guardrail.js
 *
 * Return guardrails filtered by phase.
 *
 * ctx.phase  — one of VALID_PHASES (see constants.js)
 * ctx.format — "json" or undefined (default: markdown string)
 */

import { loadMergedGuardrails, filterByPhase } from "../../lib/guardrail.js";
import { FlowCommand } from "./base-command.js";
import { VALID_GUARDRAIL_PHASES } from "../../lib/constants.js";

const PHASE_ALIASES = Object.freeze({
  impl: "task-impl",
});

function normalizeGuardrailPhase(phase) {
  return PHASE_ALIASES[phase] || phase;
}

/**
 * Render guardrails as Markdown text.
 * @param {Object[]} guardrails
 * @returns {string}
 */
function toMarkdown(guardrails) {
  return guardrails
    .map((g) => `## Guardrail: ${g.title} (${g.id})\n\n${g.body.trim()}`)
    .join("\n\n");
}

export default class GetGuardrailCommand extends FlowCommand {
  constructor() {
    super({ requiresFlow: false });
  }

  execute(ctx) {
    const { root } = ctx;
    const { phase, format } = ctx;

    const normalizedPhase = normalizeGuardrailPhase(phase);

    if (!phase) {
      throw new Error(`phase required. valid: ${VALID_GUARDRAIL_PHASES.join(", ")} (alias: impl -> task-impl)`);
    }

    if (!VALID_GUARDRAIL_PHASES.includes(normalizedPhase)) {
      throw new Error(`unknown phase '${phase}'. valid: ${VALID_GUARDRAIL_PHASES.join(", ")} (alias: impl -> task-impl)`);
    }

    const guardrails = loadMergedGuardrails(root);
    const filtered = filterByPhase(guardrails, normalizedPhase);

    if (format === "json") {
      return {
        phase: normalizedPhase,
        count: filtered.length,
        guardrails: filtered.map((g) => ({
          id: g.id,
          title: g.title,
          body: g.body.trim(),
          meta: g.meta,
        })),
      };
    }

    // Default: return markdown string
    return { markdown: toMarkdown(filtered) };
  }
}

