/** Token sub-fields that the Logger / canonical command view emit per agent entry. */
export const TOKEN_KEYS = ["input", "output", "cacheRead", "cacheCreation"];

/** Activity counter names consumed by the Report view (flat aggregates). */
export const ACTIVITY_COUNTERS = ["docsRead", "srcRead", "question", "issueLog"];

/** Fresh zero-filled token accumulator (never share the literal — callers mutate). */
function zeroTokens() {
  return Object.fromEntries(TOKEN_KEYS.map((k) => [k, 0]));
}

function zeroProviderBucket() {
  return {
    callCount: 0,
    responseChars: 0,
    durationMs: 0,
    tokens: zeroTokens(),
    cost: 0,
    costIncomplete: false,
    models: {},
  };
}

/**
 * Build an aggregated metricsSummary view over the flat append-only
 * `state.metrics` entry array. Returns `{ flow, tasks: { <id>: {...} }, total }`,
 * where each leaf is `{ <phase>: { <counter>: N, ... } }` with agent-call
 * aggregates (callCount, responseChars, durationMs, tokens, cost, models)
 * summed when present.
 *
 * spec 253 R28: This summary is **audit-only raw totals**. Reset entries
 * (e.g. `{ counter: "gateRetry"|"reviewRetry", reset: true }` from
 * `flow set retry reset ...`) are NOT interpreted here — the raw FAIL
 * count accumulates across resets so the audit trail is preserved.
 * Consumers needing the *current* retry count (post-reset) must call
 * `countGateRetry` / `countReviewRetry` instead.
 */
export function buildMetricsSummary(entries) {
  const summary = { flow: {}, tasks: {}, total: {} };
  if (!Array.isArray(entries) || entries.length === 0) return summary;

  for (const entry of entries) {
    if (!entry || !entry.phase) continue;
    const taskId = entry.taskId ?? null;
    const bucket = taskId == null
      ? summary.flow
      : (summary.tasks[taskId] = summary.tasks[taskId] || {});
    applyEntry(bucket, entry);
    applyEntry(summary.total, entry);
  }
  return summary;
}

function applyEntry(bucket, entry) {
  const p = bucket[entry.phase] = bucket[entry.phase] || {};
  if (entry.counter) {
    p[entry.counter] = (p[entry.counter] || 0) + (entry.delta ?? 1);
  }
  if (entry.kind !== "agent") return;
  p.callCount = (p.callCount || 0) + (entry.callCount || 0);
  p.responseChars = (p.responseChars || 0) + (entry.responseChars || 0);
  if (entry.durationMs != null) p.durationMs = (p.durationMs || 0) + entry.durationMs;
  if (entry.tokens) {
    p.tokens = p.tokens || zeroTokens();
    for (const k of TOKEN_KEYS) p.tokens[k] += entry.tokens[k] || 0;
  }
  if (entry.cost != null) p.cost = (p.cost || 0) + entry.cost;
  if (entry.costIncomplete) p.costIncomplete = true;
  if (entry.model) {
    p.models = p.models || {};
    p.models[entry.model] = (p.models[entry.model] || 0) + 1;
  }
  applyProviderEntry(p, entry);
}

function applyProviderEntry(phaseBucket, entry) {
  const provider = normalizeAgentMetricDimension(entry.provider);
  const profileKey = normalizeAgentMetricDimension(entry.profileKey);
  phaseBucket.providers = phaseBucket.providers || {};
  const providerBucket = phaseBucket.providers[provider] = phaseBucket.providers[provider] || {};
  const bucket = providerBucket[profileKey] = providerBucket[profileKey] || zeroProviderBucket();

  bucket.callCount += entry.callCount || 0;
  bucket.responseChars += entry.responseChars || 0;
  if (entry.durationMs != null) bucket.durationMs += entry.durationMs;
  if (entry.tokens) {
    for (const k of TOKEN_KEYS) bucket.tokens[k] += entry.tokens[k] || 0;
  }
  if (entry.cost != null) bucket.cost += entry.cost;
  if (entry.costIncomplete) bucket.costIncomplete = true;
  if (entry.model) bucket.models[entry.model] = (bucket.models[entry.model] || 0) + 1;
}

/**
 * Extract report-shape totals (activity counters + agent runtime metrics) from
 * a `metricsSummary.total` view. The report uses a flattened token shape
 * (`input`/`output`/… on the root of `tokens`), so this path cannot share the
 * `mergeAgentAggregates` routine directly; it iterates per-phase and pulls
 * duration into a list.
 */
export function buildReportTotals(summaryTotal) {
  const activity = Object.fromEntries(ACTIVITY_COUNTERS.map((k) => [k, 0]));
  const tokens = { ...zeroTokens(), cost: null, callCount: 0, durationMs: 0, phaseDurations: [] };
  for (const [phase, data] of Object.entries(summaryTotal || {})) {
    for (const k of ACTIVITY_COUNTERS) activity[k] += data[k] || 0;
    if (data.tokens) for (const k of TOKEN_KEYS) tokens[k] += data.tokens[k] || 0;
    if (data.cost != null) tokens.cost = (tokens.cost || 0) + data.cost;
    tokens.callCount += data.callCount || 0;
    if (data.durationMs) {
      tokens.durationMs += data.durationMs;
      tokens.phaseDurations.push({ phase, durationMs: data.durationMs });
    }
  }
  return { activity, tokens };
}

function resolveActiveStepMaxAttempts(state, active) {
  if (!active?.id) return null;
  const maxAttempts = resolveMaxAttempts({
    scope: active.id === "task-review" ? "task" : "flow",
    stepId: active.id,
    context: state,
  });
  return Number.isSafeInteger(maxAttempts) && maxAttempts >= 1 ? maxAttempts : null;
}

function resolveReviewRetryWindow(state, active, route) {
  const scope = route.taskId === null ? "flow" : "task";
  const stepId = route.taskId === null ? active.id : "task-review";
  if (state.attempt?.failure?.retryKind === "tooling") {
    const retryLimit = resolveToolingMaxAttempts({ scope, stepId, context: state });
    if (!Number.isSafeInteger(retryLimit) || retryLimit < 0) return null;
    return Object.freeze({
      attempts: (state.attempt.consumption?.tooling ?? 0) + 1,
      max: retryLimit + 1,
    });
  }
  const max = resolveMaxAttempts({ scope, stepId, context: state });
  return Number.isSafeInteger(max) && max >= 1
    ? Object.freeze({ attempts: state.attempt?.sequence ?? 0, max })
    : null;
}

function buildStatusRetryRecoveryView(root, flowState, input, options = {}) {
  let recoveryPlan;
  try {
    recoveryPlan = inspectRetryRecoveryPlan({
      flowManager: options.flowManager,
      state: flowState,
      executionRoot: options.executionRoot || root,
      artifactRoot: options.artifactRoot || options.flowManager?.mainRoot || root,
    });
  } catch {
    recoveryPlan = null;
  }
  return buildStateRetryRecoveryView({
    root,
    flowState,
    recoveryPlan,
    ...input,
  });
}

function finalRegressionStatus(artifact) {
  if (artifact === null) return null;
  validateFinalRegressionResult(artifact);
  return {
    result: artifact.result,
    completed: artifact.completed,
    failureKind: artifact.failureKind,
    failureCategory: artifact.failureCategory || null,
    rawOutputPath: artifact.rawOutputPath,
    fixAttempts: artifact.fixAttempts ?? null,
    selectedAction: artifact.selectedAction || null,
    remainingRisk: artifact.remainingRisk || null,
  };
}

class CanonicalStatusArtifacts {
  constructor({ flowManager, state } = {}) {
    if (!flowManager || typeof flowManager.readArtifact !== "function") {
      throw new Error("canonical status requires FlowManager.readArtifact");
    }
    if (state?.schemaRevision !== CURRENT_FLOW_SCHEMA_REVISION || typeof state.specId !== "string" || state.specId === "") {
      throw new Error("canonical status requires a Version-1 Flow state");
    }
    this.flowManager = flowManager;
    this.state = state;
    this.specId = state.specId;
    this.runId = state.runId;
    Object.freeze(this);
  }

  #read(logicalKey, { optional = false } = {}) {
    return this.flowManager.readArtifact({
      specId: this.specId,
      logicalKey,
      consumerNodeId: "flow",
      optional,
    });
  }

  requirements() {
    return new CanonicalSpecRecord({
      flowManager: this.flowManager,
      state: { schemaRevision: CURRENT_FLOW_SCHEMA_REVISION, specId: this.specId },
      consumerNodeId: "system",
    }).requirements();
  }

  mappedRequirementIds(requirements) {
    const artifact = this.flowManager.readArtifact({
      specId: this.specId,
      logicalKey: "file.map",
      consumerNodeId: "system",
      optional: true,
    });
    if (artifact === null) return new Set();
    const fileMap = CanonicalFileMap.fromBytes(artifact.bytes)
      .assertAgainstSpec({ requirements })
      .toJSON();
    return new Set(Object.keys(fileMap));
  }

  finalRegression() {
    const resolved = this.#read("final.regression", { optional: true });
    if (resolved === null) return null;
    return CanonicalCommandAttemptArtifactHistory.fromBytes({
      logicalKey: "final.regression",
      bytes: resolved.bytes,
    }).current.payload;
  }

  requirementTestLifecycle() {
    // The plan's catalog contract authorizes report-style read projections;
    // status is such a read-only projection, not a lifecycle worker.
    const resolved = this.flowManager.readArtifact({
      specId: this.specId,
      logicalKey: "test.requirement.plan",
      consumerNodeId: "report",
      optional: true,
    });
    if (resolved === null) return null;
    const plan = RequirementTestPlanArtifact.fromJSON(JSON.parse(resolved.bytes.toString("utf8"))).plan;
    const active = plan.activeWorkItem();
    return {
      activeRequirementId: active?.requirementId ?? null,
      semanticMode: this.state.policy.autoApprove ? "auto" : "manual",
      requirements: plan.workItems.map((item) => {
        const auto = { attempts: item.budget.autoSemantic, remaining: REQUIREMENT_TEST_SEMANTIC_LIMIT - item.budget.autoSemantic };
        const manual = { attempts: item.budget.manualSemantic, remaining: REQUIREMENT_TEST_SEMANTIC_LIMIT - item.budget.manualSemantic };
        const selected = this.state.policy.autoApprove ? auto : manual;
        return {
          requirementId: item.requirementId,
          status: item.status,
          bundleRevision: item.bundleRevision?.revision ?? null,
          semantic: {
            mode: this.state.policy.autoApprove ? "auto" : "manual",
            attempts: selected.attempts,
            remaining: selected.remaining,
            auto,
            manual,
          },
          tooling: {
            attempts: item.budget.tooling,
            remaining: REQUIREMENT_TEST_TOOLING_LIMIT - item.budget.tooling,
          },
        };
      }),
    };
  }

  deferredFindings() {
    const resolved = this.#read("flow.findings", { optional: true });
    if (resolved === null) return {
      count: 0,
      sourceSteps: [],
      artifactPath: FLOW_ARTIFACT_CONTRACTS.resolve("flow.findings").relativePath,
    };
    const stored = new FlowFindingsArtifact(JSON.parse(resolved.bytes.toString("utf8")));
    const entries = stored.entries.filter((entry) => entry.runId === this.runId);
    return {
      count: entries.length,
      sourceSteps: [...new Set(entries.map((entry) => entry.sourceStep))],
      artifactPath: resolved.relativePath,
    };
  }

  taskReviewConvergence() {
    const cycle = ReviewFindingCycle.fromActivityLedger({
      runId: this.runId,
      activities: this.flowManager.activityLedger(this.specId),
    });
    return new TaskReviewConvergenceEvidence({ flowManager: this.flowManager, state: this.state, cycle }).status();
  }

  implementationReviewConvergence() {
    if (typeof this.flowManager.readArtifact !== "function") return null;
    const cycle = ReviewFindingCycle.fromActivityLedger({
      runId: this.runId,
      activities: this.flowManager.activityLedger(this.specId),
    });
    return ImplementationReviewRecurrenceStatus.fromCanonical({
      flowManager: this.flowManager,
      state: this.state,
      cycle,
    }).toJSON();
  }

  gateObservationConvergence() {
    const status = GateObservationConvergenceStatus.fromCanonical({
      flowManager: this.flowManager,
      state: this.state,
    });
    return status.empty ? null : status.toJSON();
  }
}

function buildStatusGateViews(state, active, root, options = {}) {
  if (!active || !active.id.endsWith("-gate")) return null;
  const resolvedMaxAttempts = resolveActiveStepMaxAttempts(state, active);
  if (resolvedMaxAttempts == null) return null;
  const gateRecoveryDisplay = resolveGateRecoveryDisplayPhase({
    root,
    flowState: state,
    stepId: active.id,
    maxAttempts: resolvedMaxAttempts,
  });
  if (!gateRecoveryDisplay) return null;
  const retryRecovery = buildStatusRetryRecoveryView(root, state, {
    kind: "gate",
    phase: gateRecoveryDisplay.phase,
    attempts: gateRecoveryDisplay.attempts,
    max: gateRecoveryDisplay.max,
  }, options);
  const gateStop = retryRecovery?.attempts >= retryRecovery?.max ? retryRecovery : null;
  return { gateStop, retryRecovery };
}

function buildStatusReviewViews(state, active, root, options = {}) {
  if (!active || !active.id.endsWith("-review") || typeof options.flowManager?.canonicalState !== "function") return null;
  const canonical = options.flowManager.canonicalState(state.specId);
  if (canonical?.attempt?.failure == null || canonical.attempt.nodeId !== active.id) return null;
  const route = retryEvidenceRouteForNode(canonical, active.id);
  if (route === null) return null;
  const retryWindow = resolveReviewRetryWindow(canonical, active, route);
  if (retryWindow === null) return null;
  const retryRecovery = buildStatusRetryRecoveryView(root, canonical, {
    kind: "review",
    phase: route.phase,
    attempts: retryWindow.attempts,
    max: retryWindow.max,
  }, options);
  return retryRecovery === null ? null : { retryRecovery };
}

function validateRunId(runId) {
  if (runId == null) return null;
  if (typeof runId !== "string" || runId.length < 1 || runId.length > 200) {
    throw new Error("invalid runId: expected a non-empty string token from 1 to 200 characters");
  }
  return runId;
}

function buildStatusOutput(state, root, options = {}) {
  const details = options.details === true;
  const artifacts = state?.schemaRevision === CURRENT_FLOW_SCHEMA_REVISION
    ? new CanonicalStatusArtifacts({ flowManager: options.flowManager, state })
    : null;
  const phase = state.steps ? derivePhase(state) : null;
  // spec 251 R42: count leaf steps via flattenSteps so nested impl-phase
  // children (test-execute, test-result-review, retro, finalize-*) are
  // reflected accurately in stepsProgress.
  const leafSteps = state.steps ? flattenSteps(state.steps) : [];
  const active = findLatestInProgressLeaf(leafSteps);
  const doneSteps = leafSteps.filter((s) => s.status === "done" || s.status === "skipped").length;
  const totalSteps = leafSteps.length;
  const requirements = artifacts ? artifacts.requirements() : [];
  const mappedReqs = artifacts ? artifacts.mappedRequirementIds(requirements).size : 0;
  const totalReqs = requirements.length;
  const reviewAction = null;
  const gateViews = state.specId ? buildStatusGateViews(state, active, root, options) : null;
  const reviewViews = state.specId ? buildStatusReviewViews(state, active, root, options) : null;
  const retryRecovery = reviewViews?.retryRecovery || gateViews?.retryRecovery || null;
  const recoveryDiagnostics = (
    reviewAction
    || retryRecovery
    || gateViews?.gateStop
  ) ? {
      ...(reviewAction && { review: reviewAction }),
      ...(reviewViews?.retryRecovery && { review: reviewViews.retryRecovery }),
      ...(gateViews?.retryRecovery && { gate: gateViews.retryRecovery }),
      ...(gateViews?.gateStop && { gateStopped: true }),
    } : null;

  // autoApprove is always false in preparing state
  const autoApprove = state.lifecycle === "preparing" ? false : (state.autoApprove || false);
  const deferredFindings = artifacts
    ? artifacts.deferredFindings()
    : {
      count: 0,
      sourceSteps: [],
      artifactPath: FLOW_ARTIFACT_CONTRACTS.resolve("flow.findings").relativePath,
    };
  const finalRegression = finalRegressionStatus(artifacts?.finalRegression() ?? null);
  const requirementTestLifecycle = artifacts?.requirementTestLifecycle() ?? null;
  const taskReviewConvergence = artifacts?.taskReviewConvergence() ?? [];
  const implementationReviewConvergence = artifacts?.implementationReviewConvergence() ?? null;
  const gateObservationConvergence = artifacts?.gateObservationConvergence() ?? null;
  const completion = new FlowCompletion(state);
  const advisory = advisorySummary(state);

  const output = {
    active: completion.active,
    specId: state.specId,
    baseBranch: state.baseBranch,
    featureBranch: state.featureBranch,
    worktree: state.worktree || false,
    issue: state.issue || null,
    runId: state.runId || null,
    phase,
    steps: state.steps || [],
    stepsProgress: { done: doneSteps, total: totalSteps },
    requirements,
    requirementsProgress: { mapped: mappedReqs, total: totalReqs },
    ...(requirementTestLifecycle !== null && { requirementTestLifecycle }),
    ...(deferredFindings.count > 0 && { deferredFindings }),
    ...(finalRegression && { finalRegression }),
    ...(taskReviewConvergence.length > 0 && { taskReviewConvergence }),
    ...(implementationReviewConvergence !== null && { implementationReviewConvergence }),
    ...(gateObservationConvergence !== null && { gateObservationConvergence }),
    ...(recoveryDiagnostics && { recoveryDiagnostics }),
    mergeStrategy: state.mergeStrategy || null,
    autoApprove,
    completion: completion.toJSON(),
    assurance: advisory.length > 0 ? "advisory" : "strict",
    ...(state.policy?.nonblocking?.enabled === true && { nonblocking: state.policy.nonblocking }),
    ...(advisory.length > 0 && { advisorySummary: advisory }),
  };

  if (!details) return output;

  const broadMode = buildBoundedBroadModeHistory(state, BROAD_MODE_HISTORY_MAX_ENTRIES);
  return {
    ...output,
    request: state.request || null,
    notes: state.notes || [],
    metrics: state.metrics || [],
    metricsSummary: buildMetricsSummary(state.metrics || []),
    broadModeHistory: broadMode.entries,
    broadModeHistoryTotal: broadMode.total,
    broadModeHistoryTruncated: broadMode.truncated,
  };
}

export default class GetStatusCommand extends FlowCommand {
  constructor() {
    super({
      requiresFlow: false,
      targetGuard: false,
      explicitTargetResolution: true,
      positionalRunIdTarget: true,
    });
  }

  execute(ctx) {
    const runId = validateRunId(ctx.runId);
    const options = { details: ctx.details === true };

    if (ctx.flowResolutionError) {
      return Envelope.fail(
        "get",
        "status",
        ctx.flowResolutionError.code || "FLOW_TARGET_NOT_FOUND",
        ctx.flowResolutionError.message,
        ctx.flowResolutionError.data,
      );
    }

    if (runId) {
      // The binding already selected the only permissible worktree target.
      // A positional runId validates that state instead of redirecting it.
      const resolvedState = ctx.preparingFlowState ?? ctx.flowState;
      const state = resolvedState || ctx.flowManager.resolveByRunId(runId);
      if (!state) {
        throw new Error(`RUN_ID_NOT_FOUND: ${runId}`);
      }
      const status = buildStatusOutput(state, ctx.root, {
        ...options,
        executionRoot: ctx.executionRoot || ctx.root,
        flowManager: ctx.flowManager,
      });
      try {
        const positionalExpectation = new FlowTargetExpectation({ expectRunId: runId });
        const positionalMismatch = positionalExpectation.mismatchAgainst(state);
        if (positionalMismatch) {
          return buildTargetMismatchEnvelope({ type: "get", key: "status", data: positionalMismatch });
        }
        const expectation = new FlowTargetExpectation({
          expectIssue: ctx.expectIssue,
          expectNoIssue: ctx.expectNoIssue,
          expectSpec: ctx.expectSpec,
          expectRunId: ctx.expectRunId,
        });
        const mismatch = expectation.mismatchAgainst(state);
        return mismatch ? buildTargetMismatchEnvelope({
          type: "get",
          key: "status",
          data: {
            ...mismatch,
            ...(!("expectedRunId" in mismatch) && {
              expectedRunId: runId,
              activeRunId: state.runId || null,
            }),
          },
        }) : status;
      } catch (err) {
        return Envelope.fail("get", "status", "ARGS_ERROR", err.message);
      }
    }

    const currentContextMismatch = targetMismatchEnvelopeForInput({
      type: "get",
      key: "status",
      input: { expectSpec: ctx.expectSpec, expectRunId: ctx.expectRunId },
      flowState: ctx.flowState,
    });
    if (currentContextMismatch) return currentContextMismatch;

    // Default: context-based resolution. No active flow is a normal state,
    // not an error — consumers discriminate via the `active` field.
    if (!ctx.flowState) {
      return { active: false };
    }
    const status = buildStatusOutput(ctx.flowState, ctx.root, {
      ...options,
      executionRoot: ctx.executionRoot || ctx.root,
      flowManager: ctx.flowManager,
    });
    return targetMismatchEnvelopeForInput({
      type: "get",
      key: "status",
      input: ctx,
      flowState: ctx.flowState,
    }) || status;
  }
}

import fs from "node:fs";
import path from "node:path";
import { AtomicJsonFile } from "../../lib/atomic-json-file.js";
import { Envelope } from "../../lib/flow-envelope.js";
import { listUncommittedFiles, runGit } from "../../lib/git-helpers.js";
import { RepositoryFlowOperationLock } from "../../lib/repository-maintenance-lock.js";
import { WorktreeFlowIdentity } from "../../lib/worktree-flow-binding.js";
import { FlowCommand } from "./base-command.js";
import { PRODUCT } from "../../lib/product.js";
import {
  deleteFeatureBranchForCleanup,
  removeWorktreeForCleanup,
} from "./run-finalize-cleanup.js";

const ABORT_PHASES = Object.freeze([
  "prepared",
  "worktree-removed",
  "branch-deleted",
  "active-cleared",
  "spec-removed",
]);
const GIT_OBJECT_ID = /^(?:[a-f0-9]{40}|[a-f0-9]{64})$/;

class FlowAbortJournal {
  static pathFor(root, specId) {
    return path.join(root, PRODUCT.managedPath("recovery", "flow-abort", `${specId}.json`));
  }

  constructor({ root, state, worktreePath, featureSha }) {
    const directory = path.join(root, PRODUCT.managedPath("recovery", "flow-abort"));
    fs.mkdirSync(directory, { recursive: true });
    this.file = new AtomicJsonFile(FlowAbortJournal.pathFor(root, state.specId));
    this.value = this.file.read(null) || {
      version: 1,
      runId: state.runId,
      specId: state.specId,
      featureBranch: state.featureBranch,
      baseBranch: state.baseBranch,
      worktreePath: worktreePath || null,
      featureSha,
      phase: "prepared",
      updatedAt: new Date().toISOString(),
    };
    if (
      this.value.version !== 1
      || this.value.runId !== state.runId
      || this.value.specId !== state.specId
      || this.value.featureBranch !== state.featureBranch
      || this.value.baseBranch !== state.baseBranch
      || !ABORT_PHASES.includes(this.value.phase)
      || (
        state.featureBranch === null
          ? this.value.featureSha !== null
          : !GIT_OBJECT_ID.test(String(this.value.featureSha))
      )
    ) {
      throw new Error("flow abort journal does not match the selected flow");
    }
    this.file.write(this.value);
  }

  atLeast(phase) {
    return ABORT_PHASES.indexOf(this.value.phase) >= ABORT_PHASES.indexOf(phase);
  }

  advance(phase) {
    if (this.atLeast(phase)) return;
    if (ABORT_PHASES.indexOf(phase) !== ABORT_PHASES.indexOf(this.value.phase) + 1) {
      throw new Error(`invalid flow abort transition: ${this.value.phase} -> ${phase}`);
    }
    this.value = { ...this.value, phase, updatedAt: new Date().toISOString() };
    this.file.write(this.value);
  }
}

function branchSha(root, branch) {
  const result = runGit(["-C", root, "rev-parse", `refs/heads/${branch}`]);
  if (!result.ok || !GIT_OBJECT_ID.test(result.stdout.trim())) {
    throw new Error(`flow abort feature branch could not be resolved: ${branch}`);
  }
  return result.stdout.trim();
}

function outsideTargetSpec(filePath, relativeSpecDirectory) {
  return filePath !== relativeSpecDirectory && !filePath.startsWith(`${relativeSpecDirectory}/`);
}

export class RunAbortCommand extends FlowCommand {
  constructor() {
    super({ explicitTargetResolution: true, recoveryTargetResolution: true });
  }

  async execute(ctx) {
    const state = ctx.flowState;
    const specLocation = ctx.specLocation || ctx.flowManager.specLocation(state.specId);
    const repositoryRoot = specLocation.repositoryRoot;
    const { worktreePath } = ctx.flowManager.resolveWorktreePaths(state);
    const ownsFeatureBranch = state.featureBranch !== null && state.featureBranch !== state.baseBranch;
    const operation = new RepositoryFlowOperationLock({ mainRoot: repositoryRoot });
    const operationOwnerToken = operation.acquire();
    try {
      const journal = new FlowAbortJournal({
        root: repositoryRoot,
        state,
        worktreePath,
        featureSha: fs.existsSync(FlowAbortJournal.pathFor(repositoryRoot, state.specId))
          || state.featureBranch === null
          ? null
          : branchSha(repositoryRoot, state.featureBranch),
      });

      if (!journal.atLeast("worktree-removed")) {
        if (state.worktree && worktreePath && fs.existsSync(worktreePath)) {
          const worktreeManager = ctx.flowManager.forRoot(worktreePath, { specId: state.specId });
          const expectedBinding = worktreeManager.usesWorktreeFlowBinding()
            ? new WorktreeFlowIdentity({
                runId: state.runId,
                issue: state.issue ?? null,
                specId: state.specId,
                worktreePath,
              })
            : null;
          const removed = removeWorktreeForCleanup({
            mainRepoPath: repositoryRoot,
            worktreePath,
            featureBranch: state.featureBranch,
            force: ctx.force === true,
            expectedBinding,
          });
          if (!removed.ok) return removed.env;
        } else if (!state.worktree && ownsFeatureBranch) {
          const unrelatedDirty = listUncommittedFiles({ cwd: repositoryRoot })
            .filter((filePath) => outsideTargetSpec(filePath, specLocation.relativeDirectory));
          if (unrelatedDirty.length > 0) {
            return Envelope.fail(
              "run",
              "abort",
              "ABORT_UNRELATED_DIRTY",
              "Non-worktree abort stopped because unrelated dirty files are present.",
              { dirtyFiles: unrelatedDirty },
            );
          }
          const switched = runGit(["-C", repositoryRoot, "switch", state.baseBranch]);
          if (!switched.ok) {
            return Envelope.fail("run", "abort", "ABORT_BASE_SWITCH_FAILED", switched.stderr || switched.stdout);
          }
        }
        journal.advance("worktree-removed");
      }

      if (!journal.atLeast("branch-deleted")) {
        if (ownsFeatureBranch) {
          const branch = runGit(["-C", repositoryRoot, "rev-parse", "--verify", `refs/heads/${state.featureBranch}`]);
          if (branch.ok) {
            const deleted = deleteFeatureBranchForCleanup({
              mainRepoPath: repositoryRoot,
              featureBranch: state.featureBranch,
              expectedSha: journal.value.featureSha,
            });
            if (!deleted.ok) return deleted.env;
          }
        }
        journal.advance("branch-deleted");
      }

      if (!journal.atLeast("active-cleared")) {
        ctx.flowManager.removeActiveFlow(state.specId, { operationOwnerToken });
        journal.advance("active-cleared");
      }

      if (!journal.atLeast("spec-removed")) {
        fs.rmSync(specLocation.directory, { recursive: true });
        journal.advance("spec-removed");
      }

      return {
        status: "aborted",
        specId: state.specId,
        removed: {
          worktree: state.worktree ? worktreePath : null,
          branch: ownsFeatureBranch ? state.featureBranch : null,
          specDir: specLocation.relativeDirectory,
        },
      };
    } finally {
      operation.release();
    }
  }
}

export default RunAbortCommand;

/**
 * src/flow/lib/run-auto-check.js
 *
 * `sennel flow run auto-check` — phase-aware eligibility check for auto mode.
 *
 * Flow (spec 220):
 *   - resolve the target flow (active flow.json or preparing record via --run-id)
 *   - delegate input resolution to `resolve-auto-check-input` which picks the
 *     payload based on phase markers in flow state (see that module for rules)
 *   - if the resolver signals skip (spec approved), return without invoking
 *     the AI; exact V1 state never caches the verdict
 *   - otherwise: static gates (keyword match, sync) → AI scoring → compose
 *     eligible verdict
 *
 * The preparing-state persistence path is what allows the subsequent
 * `flow set auto on` to trust this verdict instead of re-invoking the AI
 * with a different input (spec 218).
 *
 * Spec 208: R1 / R2 / R3 / R4 / R5 / R6 / R13.
 * Spec 218: preparing-flow persistence for split-brain elimination.
 * Spec 220: phase-aware input, spec-approved skip, --run-id required for
 *           preparing-mode targeting (no auto-select).
 *
 * ctx inputs (merged from CLI by FlowCommand base):
 *   - runId: optional for active flow; REQUIRED in preparing mode.
 */

import { FlowCommand } from "./base-command.js";
import { evaluateStaticGates } from "./auto-check-static.js";
import { resolvePreparingRunId } from "./resolve-preparing-run-id.js";
import {
  CanonicalAutoCheckInputError,
  resolvePreparingAutoCheckInput,
  resolveAutoCheckInputForFlow,
  buildSkipVerdict,
} from "./resolve-auto-check-input.js";
import { Envelope } from "../../lib/flow-envelope.js";
import { PromptBuilder } from "../../lib/prompt-builder.js";
import {
  PromptBatchExecutor,
  PromptBatchPlan,
  PromptCompletionReducer,
  PromptExecutionLimit,
  PromptRequestLimit,
  PromptBatchingError,
} from "../../lib/prompt-batching.js";
import {
  AgentFailure,
  AgentPermissionConfigurationFailure,
} from "../../lib/agent-failure.js";

const AUTO_CHECK_ROLE = `You evaluate whether a feature request can safely proceed in Spec-Driven Development "auto mode" —
meaning the AI drafts, specs, and implements without human confirmation loops.`;

const AUTO_CHECK_RULES = `Score the following request on six dimensions (0/1/2 each).

- specBuildability (weight 3) — can Goal / Scope / Acceptance be derived?
  0 = cannot determine Goal or Acceptance without clarification
  1 = main requirements derivable but some inference needed
  2 = Goal / Scope / Acceptance all directly derivable
- ambiguity (weight 3) — is the input unambiguous?
  0 = multiple plausible interpretations
  1 = minor ambiguity survivable with defaults
  2 = no meaningful ambiguity
- verifiability (weight 2) — can success be verified mechanically?
  0 = no observable criterion
  1 = partially subjective
  2 = clear, testable criterion
- scopeBoundedness (weight 2) — is the scope bounded?
  0 = open-ended
  1 = mostly bounded
  2 = clearly bounded
- targetSpecificity (weight 1) — are the targets specified?
  0 = unclear
  1 = partially specified
  2 = specific files/modules/commands identified
- precedent (weight 1) — is there similar prior work?
  0 = novel
  1 = partial precedent
  2 = clear precedent

Also include a temporary goal field. The goal is the concrete outcome this request asks the flow to achieve. If no concrete goal can be derived, output null.
Also include a reason field (short string, under 200 chars, Japanese).`;

export const AUTO_CHECK_SCHEMA = {
  type: "object",
  properties: {
    specBuildability: { type: "integer" },
    ambiguity: { type: "integer" },
    verifiability: { type: "integer" },
    scopeBoundedness: { type: "integer" },
    targetSpecificity: { type: "integer" },
    precedent: { type: "integer" },
    goal: { type: ["string", "null"] },
    reason: { type: "string" },
  },
  required: ["specBuildability", "ambiguity", "verifiability", "scopeBoundedness", "targetSpecificity", "precedent", "goal", "reason"],
  additionalProperties: false,
};

const AUTO_CHECK_FMT_FALLBACK = 'Output JSON only, no prose. Use these exact keys and integer scores.\nOutput JSON shape (no markdown fence, no prose):\n{"specBuildability": N, "ambiguity": N, "verifiability": N, "scopeBoundedness": N, "targetSpecificity": N, "precedent": N, "goal": "...", "reason": "..."}';

const WEIGHTS = {
  specBuildability: 3,
  ambiguity: 3,
  verifiability: 2,
  scopeBoundedness: 2,
  targetSpecificity: 1,
  precedent: 1,
};
const MAX_SCORE = Object.values(WEIGHTS).reduce((a, b) => a + b, 0) * 2; // 24
const THRESHOLD = 16;
const HARD_GATE_KEYS = ["specBuildability", "ambiguity", "verifiability"];
const CATEGORY_KEYS = Object.keys(WEIGHTS);

export function computeScore(breakdown) {
  let total = 0;
  for (const key of CATEGORY_KEYS) {
    const v = Number(breakdown?.[key] ?? 0);
    total += v * WEIGHTS[key];
  }
  return total;
}

const HARD_GATE_MIN_SUM = 2;

function computeHardGateSum(breakdown) {
  return HARD_GATE_KEYS.reduce((acc, k) => acc + Number(breakdown?.[k] ?? 0), 0);
}

export function hardGateFailed(breakdown) {
  return computeHardGateSum(breakdown) < HARD_GATE_MIN_SUM;
}

class AutoCheckResponse {
  constructor(value) {
    if (!value || typeof value !== "object" || Array.isArray(value)) {
      throw new Error("auto-check response must be a JSON object");
    }
    this.value = Object.freeze({ ...value });
    Object.freeze(this);
  }

  get goal() { return this.value.goal; }
  get reason() { return this.value.reason; }

  breakdown() {
    return sanitizeBreakdown(this.value);
  }
}

class AutoCheckResponseContract {
  parse(raw) {
    return parseAiResponse(raw);
  }
}

function parseAiResponse(text) {
  const cleaned = String(text || "").trim().replace(/^```(?:json)?|```$/g, "").trim();
  const start = cleaned.indexOf("{");
  const end = cleaned.lastIndexOf("}");
  if (start < 0 || end < 0) throw new Error("no JSON object in AI response");
  return new AutoCheckResponse(JSON.parse(cleaned.slice(start, end + 1)));
}

function emptyBreakdown() {
  const b = {};
  for (const k of CATEGORY_KEYS) b[k] = 0;
  return b;
}

function sanitizeBreakdown(raw) {
  const b = {};
  for (const k of CATEGORY_KEYS) {
    const v = Number(raw?.[k]);
    b[k] = Number.isFinite(v) ? Math.max(0, Math.min(2, Math.floor(v))) : 0;
  }
  return b;
}

function goalMissing(goal) {
  if (goal == null) return true;
  const normalized = String(goal).trim().toLowerCase();
  return normalized === "" || ["unknown", "n/a", "na", "not specified", "null"].includes(normalized);
}

async function scoreWithAi(container, inputText) {
  let agent;
  try {
    agent = container.get("agent");
  } catch (err) {
    return { breakdown: emptyBreakdown(), reason: `agent unavailable: ${err.message}`, ok: false };
  }
  let resolvedAgent;
  try {
    resolvedAgent = agent?.resolve?.("flow.auto-check");
  } catch (error) {
    const failure = error instanceof AgentFailure ? error : AgentFailure.from(error);
    return { breakdown: emptyBreakdown(), reason: failure.message, failure: failure.toJSON(), ok: false };
  }
  if (!resolvedAgent) {
    const failure = new AgentPermissionConfigurationFailure({
      message: "no agent profile for auto-check",
    });
    return { breakdown: emptyBreakdown(), reason: failure.message, failure: failure.toJSON(), ok: false };
  }
  const pb = new PromptBuilder();
  pb.setRole(AUTO_CHECK_ROLE);
  pb.setRules(AUTO_CHECK_RULES);
  pb.setJsonSchema(AUTO_CHECK_SCHEMA);
  pb.setFmtFallback(AUTO_CHECK_FMT_FALLBACK);
  pb.addUserPrompt("## Input text (request / Issue body)", inputText);
  const built = pb.build();

  let response;
  try {
    const maxCharacters = Math.min(agent.promptCharacterLimit ?? 120_000, 120_000);
    const limit = new PromptRequestLimit({ maxCharacters });
    const plan = PromptBatchPlan.fromRequest({ request: built, limit, id: "auto-check-input" });
    const executionLimit = new PromptExecutionLimit({
      maxRequestCharacters: maxCharacters,
      maxResponseCharacters: 120_000,
      maxBatchCount: 1,
      maxProviderCallCount: 1,
      maxProtocolRetryCount: 0,
      maxSynthesisCallCount: 1,
      maxAggregateItemCount: 1,
      maxAggregateCharacters: 120_000,
    });
    response = await new PromptBatchExecutor({ executionLimit }).execute({
      plan,
      callAgent: (request, _batch, _retryIndex, _attemptContext, providerCallAdmission) => agent.call(
        request.userPrompt,
        {
          ...request,
          commandId: "flow.auto-check",
          providerCallAdmission,
        },
      ),
      projectInvocation: typeof agent.projectInvocation === "function"
        ? (request) => agent.projectInvocation(request.userPrompt, {
          ...request,
          commandId: "flow.auto-check",
        })
        : undefined,
      responseContract: new AutoCheckResponseContract(),
      reducer: new PromptCompletionReducer(),
    });
  } catch (err) {
    const failure = err instanceof PromptBatchingError && err.cause instanceof Error ? err.cause : err;
    if (failure instanceof PromptBatchingError) {
      return {
        breakdown: emptyBreakdown(), reason: failure.message,
        failure: { code: failure.code, message: failure.message, details: failure.details }, ok: false,
      };
    }
    const agentFailure = failure instanceof AgentFailure ? failure : AgentFailure.from(failure);
    return {
      breakdown: emptyBreakdown(),
      reason: `agent call failed: ${agentFailure.message}`,
      failure: agentFailure.toJSON(),
      ok: false,
    };
  }
  const parsed = response[0].response;
  return {
    breakdown: parsed.breakdown(),
    goal: parsed.goal,
    reason: typeof parsed.reason === "string" ? parsed.reason.slice(0, 300) : "",
    ok: true,
  };
}

/**
 * Pure function: given input text and an optional AI result, compute the
 * final autoCheck envelope. Kept separate so set-auto.js can re-use the
 * same shape without re-invoking the CLI.
 */
export function composeAutoCheck({ staticGates, aiBreakdown, aiReason, aiOk, aiGoal, aiFailure = null }) {
  const staticFail = !staticGates.eligible;
  const breakdown = staticFail ? emptyBreakdown() : aiBreakdown;
  const score = computeScore(breakdown);
  const hardFail = staticFail ? false : hardGateFailed(breakdown);
  const goalFail = staticFail ? false : goalMissing(aiGoal);
  const eligible = !staticFail && aiOk && !hardFail && !goalFail && score >= THRESHOLD;
  const reasonParts = [];
  if (staticFail) {
    const hits = ["G", "H", "I"].filter((k) => staticGates[k]);
    reasonParts.push(`static gate hit: ${hits.join(", ")}`);
  }
  if (!staticFail && !aiOk) reasonParts.push(aiReason || "ai call failed");
  if (!staticFail && aiOk && hardFail) {
    reasonParts.push(`hard-gate sum ${computeHardGateSum(breakdown)} below ${HARD_GATE_MIN_SUM}`);
  }
  if (!staticFail && aiOk && !hardFail && goalFail) {
    reasonParts.push("goal missing");
  }
  if (!staticFail && aiOk && !hardFail && !goalFail && score < THRESHOLD) {
    reasonParts.push(`score ${score}/${MAX_SCORE} below threshold ${THRESHOLD}`);
  }
  if (reasonParts.length === 0 && aiReason) reasonParts.push(aiReason);
  return {
    eligible,
    score,
    maxScore: MAX_SCORE,
    threshold: THRESHOLD,
    breakdown,
    staticGates: { G: !!staticGates.G, H: !!staticGates.H, I: !!staticGates.I },
    goalGate: { checked: !staticFail && aiOk, passed: !staticFail && aiOk && !goalFail },
    reason: reasonParts.join("; "),
    ...(aiFailure ? { failure: aiFailure } : {}),
  };
}

export async function runAutoCheckCore(container, inputText) {
  const staticGates = evaluateStaticGates(inputText);
  let aiResult = { breakdown: emptyBreakdown(), reason: "", ok: true };
  if (staticGates.eligible) {
    aiResult = await scoreWithAi(container, inputText);
  }
  return composeAutoCheck({
    staticGates,
    aiBreakdown: aiResult.breakdown,
    aiReason: aiResult.reason,
    aiOk: aiResult.ok,
    aiGoal: aiResult.goal,
    aiFailure: aiResult.failure,
  });
}

export default class RunAutoCheckCommand extends FlowCommand {
  constructor() {
    super({ requiresFlow: false });
  }

  async execute(ctx) {
    // Active flow path: state is already loaded; resolve input from state phase
    if (ctx.flowManager && ctx.flowState) {
      let resolved;
      try {
        resolved = resolveAutoCheckInputForFlow({
          flowManager: ctx.flowManager,
          state: ctx.flowState,
        });
      } catch (error) {
        if (error instanceof CanonicalAutoCheckInputError) {
          return Envelope.fail("run", "auto-check", error.code, error.message);
        }
        throw error;
      }
      if (resolved.skip) {
        const verdict = buildSkipVerdict();
        return verdict;
      }
      if (resolved.fail) {
        return resolved.verdict;
      }
      const result = {
        ...(await runAutoCheckCore(this.container, resolved.text)),
        ...(resolved.goalGate ? { goalGate: resolved.goalGate } : {}),
      };
      return result;
    }

    // Preparing flow path: --run-id is required (no auto-select, no auto-skip).
    // Per spec 220 A3: both zero-preparing and multi-preparing cases without
    // --run-id surface as MISSING_RUN_ID so the caller always sees a consistent
    // error code for "you must specify which preparing flow to target".
    if (ctx.flowManager) {
      if (!ctx.runId) {
        return Envelope.fail(
          "run",
          "auto-check",
          "MISSING_RUN_ID",
          "--run-id is required when no active flow exists",
        );
      }
      const resolvedId = resolvePreparingRunId(ctx.flowManager, ctx.runId, {
        type: "run",
        key: "auto-check",
      });
      if (resolvedId.fail) return resolvedId.fail;
      const state = ctx.flowManager.loadPreparingFlow(resolvedId.runId);
      // Preparing records have no spec directory yet, so draft body is not
      // available. Only base input (issue + request) is used.
      const resolvedInput = resolvePreparingAutoCheckInput(state);
      if (resolvedInput.skip) {
        const verdict = buildSkipVerdict();
        ctx.flowManager.mutatePreparingFlow(resolvedId.runId, (s) => {
          s.autoCheck = verdict;
        });
        return verdict;
      }
      if (resolvedInput.fail) {
        ctx.flowManager.mutatePreparingFlow(resolvedId.runId, (s) => {
          delete s.autoCheck;
        });
        return resolvedInput.verdict;
      }
      const result = {
        ...(await runAutoCheckCore(this.container, resolvedInput.text)),
        ...(resolvedInput.goalGate ? { goalGate: resolvedInput.goalGate } : {}),
      };
      if (result.eligible) {
        ctx.flowManager.mutatePreparingFlow(resolvedId.runId, (s) => {
          s.autoCheck = result;
        });
      } else {
        ctx.flowManager.mutatePreparingFlow(resolvedId.runId, (s) => {
          delete s.autoCheck;
        });
      }
      return result;
    }

    // No flowManager (unusual; defensive): run stateless with empty input
    return await runAutoCheckCore(this.container, "");
  }
}

/**
 * src/flow/lib/run-lint.js
 *
 * FlowCommand: lint — run guardrail lint patterns against changed files.
 */

import { loadMergedGuardrails } from "../../lib/guardrail.js";
import { runLint } from "../../lib/lint.js";
import { FlowCommand } from "./base-command.js";

export class RunLintCommand extends FlowCommand {
  async execute(ctx) {
    const root = ctx.executionRoot || ctx.root;

    // Resolve base branch from flow state if not provided
    let base = ctx.base || "";
    if (!base) {
      const state = ctx.flowState;
      if (state?.baseBranch) {
        base = state.baseBranch;
      } else {
        throw new Error("no --base provided and no active flow found");
      }
    }

    // Load merged guardrail articles
    const allGuardrails = loadMergedGuardrails(root);
    if (allGuardrails.length === 0) {
      return {
        result: "pass",
        message: "no guardrails found",
        warnings: [],
        failures: [],
      };
    }

    const result = runLint(root, allGuardrails, base);

    for (const w of result.warnings) {
      console.error(w);
    }

    if (!result.ok) {
      throw new Error(
        [`${result.failures.length} violation(s) found`,
          ...result.failures.map((f) => `FAIL: [${f.guardrail}] ${f.file}:${f.line} — ${f.match}`),
        ].join("\n"),
      );
    }

    return {
      result: "pass",
      lintGuardrailCount: result.lintGuardrailCount,
      fileCount: result.fileCount,
      warnings: result.warnings,
      failures: [],
    };
  }
}

export default RunLintCommand;

import { FlowCommand } from "./base-command.js";
import { Envelope } from "../../lib/flow-envelope.js";
import { missingExactTargetGuardNames } from "../../lib/flow-target-guard.js";
import { flattenSteps } from "./step-tree.js";

const MAX_REASON_LENGTH = 500;
const SPEC_CORRECTION_CATEGORY = "spec-correction";
const REOPEN_CATEGORIES = new Set([undefined, "task-addition", SPEC_CORRECTION_CATEGORY]);
const PREIMPLEMENTATION_STAGES = new Set([
  "draft-refine",
  "draft-gate-repair",
  "draft-questions-review",
  "draft-questions-triage",
  "draft-questions-repair",
  "draft-coverage-review",
  "draft-coverage-triage",
  "draft-coverage-repair",
  "draft-gate",
  "spec",
  "spec-review",
  "spec-triage",
  "spec-repair",
  "spec-gate-repair",
  "spec-gate",
  "approval",
  "test-generate",
  "test-review",
  "test-repair",
  "test-gate",
]);
const SPEC_CORRECTION_STAGES = new Set([
  "implement",
  "impl-review",
  "impl-gate",
  "retro",
  "acceptance-review",
  "final-regression",
]);

function reasonFrom(value) {
  if (value == null) return "";
  if (typeof value !== "string" || value.includes("\0")) throw new Error("--reason must be a valid string");
  const reason = value.trim();
  if (reason.length > MAX_REASON_LENGTH) throw new Error(`--reason exceeds ${MAX_REASON_LENGTH} characters`);
  return reason;
}

function correctionGuardFailure(ctx, state) {
  const missing = missingExactTargetGuardNames(ctx, state);
  return missing.length === 0 ? null : Envelope.fail(
    "run",
    "reopen-draft",
    "TARGET_GUARDS_REQUIRED",
    `spec-correction requires explicit target guards: ${missing.join(", ")}`,
  );
}

function activeStep(state) {
  if (typeof state?.currentNodeId !== "string" || state.currentNodeId === "") {
    throw new Error("canonical draft reopen requires an active Attempt");
  }
  return state.currentNodeId;
}

function completedTaskCount(state) {
  return Array.isArray(state.tasks) ? state.tasks.filter((task) => task.status === "done").length : 0;
}

function routeFor({ category, state }) {
  const current = activeStep(state);
  const doneTaskCount = completedTaskCount(state);
  if (category === SPEC_CORRECTION_CATEGORY) {
    if (!SPEC_CORRECTION_STAGES.has(current)) {
      throw new Error("spec-correction reopen is only available from a supported implementation stage");
    }
    return "spec-correction";
  }
  if (category === "task-addition" || doneTaskCount > 0) {
    if (doneTaskCount === 0) {
      throw new Error("cannot reopen draft: no done task exists. Reopen is only for adding tasks mid-implementation");
    }
    return "task-addition";
  }
  if (current.startsWith("task-")) {
    throw new Error("cannot reopen draft: no done task exists. Reopen is only for adding tasks mid-implementation");
  }
  if (!PREIMPLEMENTATION_STAGES.has(current)) {
    throw new Error("reopen draft is unavailable from the active stage");
  }
  return "preimplementation";
}

/** Catalog-owned proof required only for the guarded correction route. */
export class DraftSpecCorrectionEvidence {
  constructor({ draft, specRecord } = {}) {
    if (!Buffer.isBuffer(draft) || draft.length === 0) throw new Error("canonical draft artifact is required");
    if (!Buffer.isBuffer(specRecord) || specRecord.length === 0) throw new Error("canonical spec.record artifact is required");
    this.draftBytes = draft.length;
    this.specRecordBytes = specRecord.length;
    Object.freeze(this);
  }
}

function correctionEvidence(flowManager, specId) {
  const draft = flowManager.readArtifact({ specId, logicalKey: "draft", consumerNodeId: "draft-questions-review" });
  const specRecord = flowManager.readArtifact({ specId, logicalKey: "spec.record", consumerNodeId: "draft-questions-review" });
  return new DraftSpecCorrectionEvidence({ draft: draft.bytes, specRecord: specRecord.bytes });
}

export class RunReopenDraftCommand extends FlowCommand {
  async execute(ctx) {
    if (!REOPEN_CATEGORIES.has(ctx.category)) {
      return Envelope.fail("run", "reopen-draft", "ARGS_ERROR", "--category must be task-addition or spec-correction");
    }
    const state = ctx.flowState;
    if (!state) return Envelope.fail("run", "reopen-draft", "NO_ACTIVE_FLOW", "no active flow found");
    let reason;
    try { reason = reasonFrom(ctx.reason); } catch (error) {
      return Envelope.fail("run", "reopen-draft", "INVALID_REASON", error.message);
    }
    if (ctx.category === SPEC_CORRECTION_CATEGORY) {
      if (!reason) return Envelope.fail("run", "reopen-draft", "INVALID_REASON", "--reason is required for spec-correction");
      const guardFailure = correctionGuardFailure(ctx, state);
      if (guardFailure) return guardFailure;
    }
    try {
      const previousActiveStep = activeStep(state);
      const route = routeFor({ category: ctx.category, state });
      const evidence = route === "spec-correction" ? correctionEvidence(ctx.flowManager, state.specId) : null;
      const doneTaskCount = completedTaskCount(state);
      const attempt = ctx.flowManager.canonicalState(state.specId).attempt;
      ctx.flowManager.reopenDraft({ specId: state.specId, route, reason,
        source: { stepId: previousActiveStep, attemptId: attempt.id,
          attemptSequence: attempt.sequence,
          trigger: "user invoked sennel flow reopen-draft",
          ...(evidence === null ? {} : { issueLogEvidence: {
            draftBytes: evidence.draftBytes, specRecordBytes: evidence.specRecordBytes,
          } }),
        } });
      const resetSteps = flattenSteps(ctx.flowManager.loadReadOnly(state.specId).steps)
        .filter((step) => step.status === "invalidated")
        .map((step) => step.id);
      return Envelope.ok("run", "reopen-draft", {
        reopened: true,
        mode: route === "task-addition" ? "implementation" : route === "spec-correction" ? SPEC_CORRECTION_CATEGORY : "pre-implementation",
        previousActiveStep,
        destinationStep: "draft",
        resetSteps: ["draft", ...resetSteps],
        doneTaskCount,
        taskCount: Array.isArray(state.tasks) ? state.tasks.length : 0,
        ...(evidence === null ? {} : { evidence: { draftBytes: evidence.draftBytes, specRecordBytes: evidence.specRecordBytes } }),
      });
    } catch (error) {
      const code = error.message.startsWith("cannot reopen draft") ? "NO_DONE_TASK" : "REOPEN_DRAFT_REJECTED";
      return Envelope.fail("run", "reopen-draft", code, error.message);
    }
  }
}

export default RunReopenDraftCommand;

/**
 * src/flow/lib/run-resume.js
 *
 * Resume command — return context for a registered active flow.
 */

import { FlowCommand } from "./base-command.js";
import { buildResolvedFlowContext } from "./resolve-context-envelope.js";

export default class RunResumeCommand extends FlowCommand {
  constructor() {
    super({
      requiresFlow: false,
      explicitTargetResolution: true,
      specOptionAsTarget: true,
    });
  }

  execute(ctx) {
    // A bound worktree state is execution provenance, not resume authority.
    // Normal resume must select from the active-flow registry.
    const resolved = ctx.flowManager.resolveActiveFlow(null, {
      selectSpecId: ctx.spec || undefined,
    });
    if (!resolved) throw new Error("no active flow found");
    const base = buildResolvedFlowContext({ ...ctx, flowState: resolved.state });
    return {
      ...base,
      runId: resolved.state.runId || null,
    };
  }
}

/**
 * src/flow/lib/set-auto.js
 *
 * Enable or disable autoApprove mode.
 *
 * Dual-mode operation:
 *   - Active flow: append a typed policy Activity through the Version Store.
 *   - Preparing flow (.sennel/.active-flow.<runId>, pre-prepare): mutate the
 *     preparing state so skill prelude B.0.5 can enable auto mode BEFORE
 *     `flow prepare` creates flow.json. `run-prepare-spec` inherits only the
 *     selected autoApprove policy into the new Version-1 state.
 *
 * Preparing-flow target resolution (spec 220):
 *   - --run-id is REQUIRED in preparing mode. Auto-select heuristics are gone.
 *
 * Gate on `on`:
 *   - Spec 208 R8 / R9: `on` is gated by auto-check — if the check returns
 *     eligible:false, autoApprove is NOT updated and the CLI exits non-zero
 *     with the reason on stderr.
 *   - Spec 218: When a preparing state contains a persisted `autoCheck`
 *     (written earlier by `flow run auto-check`), the verdict is trusted
 *     verbatim and the AI is NOT invoked again.
 *   - Spec 220: phase-aware input and spec-approved skip share a single
 *     catalog resolver with run-auto-check.
 *   - Spec 232: preparing autoDesired is persisted on reject; the failed
 *     verdict is not saved and neither field enters canonical flow.json.
 *
 * ctx.value — "on" | "off"
 * ctx.runId — preparing-flow target (required in preparing mode)
 */

import { FlowCommand } from "./base-command.js";
import { VALID_AUTO_VALUES } from "../../lib/constants.js";
import { runAutoCheckCore } from "./run-auto-check.js";
import { Envelope } from "../../lib/flow-envelope.js";
import { resolvePreparingRunId } from "./resolve-preparing-run-id.js";
import {
  CanonicalAutoCheckInputError,
  resolvePreparingAutoCheckInput,
  resolveAutoCheckInputForFlow,
  resolvePersistedAutoCheckTrust,
  isSpecApproved,
  buildSkipVerdict,
} from "./resolve-auto-check-input.js";

export default class SetAutoCommand extends FlowCommand {
  constructor() {
    super({ requiresFlow: false });
  }

  async execute(ctx) {
    const value = ctx.value;

    if (!value || !VALID_AUTO_VALUES.includes(value)) {
      return Envelope.fail(
        "set",
        "auto",
        "INVALID_USAGE",
        `usage: flow set auto ${VALID_AUTO_VALUES.join("|")}`,
      );
    }

    const { flowManager, flowState } = ctx;
    const preparingMode = !flowState;
    let runId = null;
    if (preparingMode) {
      const resolved = resolvePreparingRunId(flowManager, ctx.runId, {
        type: "set",
        key: "auto",
        zeroPreparingAsFail: true,
      });
      if (resolved.fail) return resolved.fail;
      runId = resolved.runId;
    }

    const updatePreparing = (updater) => flowManager.mutatePreparingFlow(runId, updater);
    const updateActivePolicy = (autoApprove) => flowManager.setAutoApprove(autoApprove, {
      ...(ctx.specId ? { specId: ctx.specId } : {}),
    });

    if (value === "off") {
      if (preparingMode) {
        updatePreparing((s) => {
          s.autoApprove = false;
          s.autoDesired = false;
        });
      } else {
        updateActivePolicy(false);
      }
      return { autoApprove: false, ...(preparingMode ? { runId } : {}) };
    }

    const state = preparingMode
      ? flowManager.loadPreparingFlow(runId)
      : flowManager.load();

    // Spec-approved skip path: skip auto-check entirely (active flow only).
    if (!preparingMode && isSpecApproved(state)) {
      const autoCheck = buildSkipVerdict();
      updateActivePolicy(true);
      return { autoApprove: true, autoCheck };
    }

    // Preparing flows retain a prior auto-check verdict so `set auto on` uses
    // the exact pre-creation input. Active Version-1 flows do not cache this
    // verdict in flow.json and resolve their catalog-backed input afresh.
    let autoCheck = state?.autoCheck || null;
    const trusted = !!autoCheck;
    if (trusted) {
      const trustFailure = resolvePersistedAutoCheckTrust(state);
      if (trustFailure) autoCheck = trustFailure;
    }
    if (!autoCheck) {
      let resolved;
      try {
        resolved = preparingMode
          ? resolvePreparingAutoCheckInput(state)
          : resolveAutoCheckInputForFlow({ flowManager, state });
      } catch (error) {
        if (error instanceof CanonicalAutoCheckInputError) {
          return Envelope.fail("set", "auto", error.code, error.message);
        }
        throw error;
      }
      if (resolved.skip) {
        autoCheck = buildSkipVerdict();
      } else if (resolved.fail) {
        autoCheck = resolved.verdict;
      } else {
        autoCheck = {
          ...(await runAutoCheckCore(this.container, resolved.text)),
          ...(resolved.goalGate ? { goalGate: resolved.goalGate } : {}),
        };
      }
      if (autoCheck.eligible) {
        // A completed auto-check is worker evidence, not a mutable
        // flow.json field.  The next owning worker publishes it as a cataloged
        // result; the user-selected policy remains the only state update here.
        if (preparingMode) updatePreparing((s) => { s.autoCheck = autoCheck; });
      }
    }

    if (!autoCheck.eligible) {
      if (preparingMode) updatePreparing((s) => { s.autoDesired = true; });
      return Envelope.fail(
        "set",
        "auto",
        "AUTO_CHECK_INELIGIBLE",
        `auto-check rejected: ${autoCheck.reason || "not eligible"}`,
        autoCheck,
      );
    }

    if (preparingMode) updatePreparing((s) => { s.autoApprove = true; });
    else updateActivePolicy(true);
    return { autoApprove: true, autoCheck, trusted, ...(preparingMode ? { runId } : {}) };
  }
}

/**
 * Enable audited broad implementation mode for task-decomposed flows.
 */

import { FlowCommand } from "./base-command.js";
import { Envelope } from "../../lib/flow-envelope.js";
