/**
 * src/flow/lib/set-init.js
 *
 * Initialize a preparing flow state before flow prepare.
 * Creates .sennel/.active-flow.<runId> with a flow.json-compatible schema.
 * Accepts --issue and --request to seed the preparing state so that a later
 * `flow prepare --run-id <id>` can inherit them.
 */

import { FlowCommand } from "./base-command.js";
import { Envelope } from "../../lib/flow-envelope.js";
import { RepositoryFlowOperationLock } from "../../lib/repository-maintenance-lock.js";
import {
  GitHubIssueSnapshotSource,
  IssueSnapshot,
  IssueSnapshotSource,
} from "./issue-snapshot-source.js";

export default class SetInitCommand extends FlowCommand {
  constructor({ issueSnapshotSource = new GitHubIssueSnapshotSource() } = {}) {
    super({ requiresFlow: false });
    if (!(issueSnapshotSource instanceof IssueSnapshotSource)) {
      throw new TypeError("issueSnapshotSource must be an IssueSnapshotSource");
    }
    this.issueSnapshotSource = issueSnapshotSource;
  }

  execute(ctx) {
    const { flowManager } = ctx;

    const extra = {};
    if (ctx.issue != null && ctx.issue !== "") {
      const n = Number(ctx.issue);
      if (!Number.isInteger(n) || n <= 0) {
        return Envelope.fail(
          "set",
          "init",
          "INVALID_ARG_VALUE",
          `--issue must be a positive integer: ${ctx.issue}`,
        );
      }
      const snapshot = this.issueSnapshotSource.load({ number: n, root: ctx.root });
      if (snapshot === null) {
        return Envelope.fail(
          "set",
          "init",
          "ISSUE_SNAPSHOT_UNAVAILABLE",
          `cannot initialize linked Issue #${n}: its immutable Issue snapshot could not be retrieved`,
        );
      }
      if (!(snapshot instanceof IssueSnapshot)) {
        throw new TypeError("issueSnapshotSource must return an IssueSnapshot or null");
      }
      snapshot.assertIdentity(n);
      extra.issue = n;
      extra.issueBody = snapshot.body;
    }
    if (ctx.request) extra.request = ctx.request;

    const remaining = flowManager.listPreparingFlows();
    if (remaining.length > 0) {
      console.error(
        `[flow] WARN: ${remaining.length} preparing flow(s) already exist: ${remaining.join(", ")}`
      );
    }

    const operationLock = new RepositoryFlowOperationLock({
      mainRoot: ctx.mainRoot || flowManager._mainRoot || ctx.root,
    });
    const operationOwnerToken = operationLock.acquire();
    try {
      const runId = flowManager.generateRunId();
      flowManager.createPreparingFlow(runId, extra, { operationOwnerToken });
      return { runId, ...extra };
    } finally {
      operationLock.release();
    }
  }
}

import { CURRENT_FLOW_SCHEMA_REVISION } from "../../lib/flow-schema-revision.js";
/**
 * src/flow/lib/set-issue-log.js
 *
 * Record an issue-log entry under the configured spec root.
 *
 * ctx.step               — step ID (required)
 * ctx.reason             — why the entry was recorded (required)
 * ctx.trigger            — what triggered the issue (optional)
 * ctx.resolution         — how the issue was resolved (optional)
 * ctx.guardrailCandidate — potential guardrail article to add (optional)
 * ctx.normalizedFindingId — normalized review finding id addressed by repair (optional)
 * ctx.repairRef          — commit hash or changed file references (optional object)
 */

import crypto from "node:crypto";
import { FlowCommand, resolveExplicitTaskOption } from "./base-command.js";
import { Envelope } from "../../lib/flow-envelope.js";
import { IssueLogDocument, IssueLogStore } from "./issue-log-store.js";

/**
 * Load issue-log.json from the resolved spec directory.
 * @param {string} root - project root
 * @param {string} specPath - relative spec path
 * @returns {{ entries: Object[] }}
 */
export function issueLogStoreForVersion(location, options = {}) {
  return IssueLogStore.forVersion({ location, ...options });
}

function canonicalIssueLogIdempotencyKey(state, entry) {
  const stableEntry = structuredClone(entry);
  // The timestamp records when the user command was first observed; it must
  // not make a restart of that same command publish a second fact.
  delete stableEntry.timestamp;
  delete stableEntry.issueLogId;
  delete stableEntry.grantId;
  const digest = crypto.createHash("sha256")
    .update(JSON.stringify({
      runId: state.runId,
      nodeId: state.currentNodeId,
      entry: stableEntry,
    }))
    .digest("hex");
  return `set-issue-log-${digest}`;
}

/**
 * Resolve the append-only issue log through the Version Store.  This is the
 * normal-runtime reader counterpart of `appendCanonicalIssueLogEntry`: it
 * accepts a Flow identity and a consumer Step, never a guessed spec path.
 */
export function loadCanonicalIssueLog(flowManager, state, { consumerNodeId = state?.currentNodeId } = {}) {
  if (state?.schemaRevision !== CURRENT_FLOW_SCHEMA_REVISION || typeof state?.specId !== "string") {
    throw new Error("canonical issue-log read requires a Version-1 Flow state");
  }
  if (!flowManager || typeof flowManager.readArtifact !== "function") {
    throw new Error("canonical issue-log read requires FlowManager.readArtifact");
  }
  if (typeof consumerNodeId !== "string" || consumerNodeId === "") {
    throw new Error("canonical issue-log read requires a consumer Step");
  }
  const artifact = flowManager.readArtifact({
    specId: state.specId,
    logicalKey: "issue.log",
    consumerNodeId,
    optional: true,
  });
  if (artifact === null) return { entries: [] };
  try {
    return new IssueLogDocument(JSON.parse(artifact.bytes.toString("utf8"))).toJSON();
  } catch (error) {
    throw new Error(`canonical issue-log is invalid: ${error.message}`);
  }
}

/**
 * Append one user-visible issue fact through the active Attempt's Activity
 * transaction.  No normal command may reconstruct `issue-log.json` from a
 * spec path or use the retired independent writer.
 */
export function appendCanonicalIssueLogEntry(flowManager, state, entry, idempotencyKey = null, admission = undefined) {
  if (state?.schemaRevision !== CURRENT_FLOW_SCHEMA_REVISION || typeof state?.specId !== "string") {
    throw new Error("canonical issue-log append requires a Version-1 Flow state");
  }
  if (!flowManager || typeof flowManager.appendIssueLog !== "function") {
    throw new Error("canonical issue-log append requires FlowManager.appendIssueLog");
  }
  return flowManager.appendIssueLog({
    specId: state.specId,
    entry,
    idempotencyKey: idempotencyKey || entry?.issueLogId || entry?.grantId
      || canonicalIssueLogIdempotencyKey(state, entry),
    admission,
  });
}

const MIN_REASON_LENGTH = 20;
const MIN_OPTIONAL_FIELD_LENGTH = 10;
const COMMIT_HASH_RE = /^[0-9a-f]{7,40}$/i;

/**
 * Issue-log scope is a command concern, not a reason to import the retired
 * mutable legacy state. The Version-1 command view already exposes Task ids
 * derived from canonical state/Activity records.
 */
function resolveTaskIdForIssueLog(state, options = {}) {
  if (Object.hasOwn(options, "taskId")) {
    if (options.taskId === null) return null;
    if (!(state.tasks || []).some((task) => task.id === options.taskId)) {
      throw new Error(`unknown task id: ${options.taskId}`);
    }
    return options.taskId;
  }
  return state.currentTaskId ?? null;
}

function validateReason(reason) {
  if ((reason ?? "").trim().length < MIN_REASON_LENGTH) {
    return Envelope.fail(
      "set",
      "issue-log",
      "INVALID_REASON",
      `--reason must be at least ${MIN_REASON_LENGTH} characters (trimmed). ` +
        `Provide a specific, descriptive reason — placeholder text is rejected.`,
    );
  }
  return null;
}

function validateOptionalIssueLogField(name, value) {
  if (value == null) return null;
  if (value.trim().length < MIN_OPTIONAL_FIELD_LENGTH) {
    return Envelope.fail(
      "set",
      "issue-log",
      "INVALID_FIELD",
      `--${name} must be at least ${MIN_OPTIONAL_FIELD_LENGTH} characters (trimmed) when provided.`,
    );
  }
  return null;
}

function normalizeRepairRef(ctx) {
  if (ctx.repairRef && typeof ctx.repairRef === "object") return ctx.repairRef;
  if (ctx.repairRefCommit) return { commit: String(ctx.repairRefCommit).trim() };
  if (ctx.repairRefFile) return { files: [String(ctx.repairRefFile).trim()] };
  return null;
}

function validateRepairRef(repairRef) {
  if (repairRef == null) return null;
  if (typeof repairRef !== "object") {
    return Envelope.fail("set", "issue-log", "INVALID_REPAIR_REF", "repairRef must be an object");
  }
  if (repairRef.commit != null && !COMMIT_HASH_RE.test(String(repairRef.commit).trim())) {
    return Envelope.fail("set", "issue-log", "INVALID_REPAIR_REF", "--repair-ref-commit must be a commit hash");
  }
  if (repairRef.files != null) {
    if (!Array.isArray(repairRef.files) || repairRef.files.some((file) => String(file || "").trim() === "")) {
      return Envelope.fail("set", "issue-log", "INVALID_REPAIR_REF", "--repair-ref-file values must be non-empty paths");
    }
  }
  if (repairRef.commit == null && repairRef.files == null) {
    return Envelope.fail("set", "issue-log", "INVALID_REPAIR_REF", "repairRef requires commit or files");
  }
  return null;
}

export default class SetIssueLogCommand extends FlowCommand {
  constructor() {
    super({ explicitTargetResolution: true });
  }

  execute(ctx) {
    if (!ctx.step || !ctx.reason) {
      return Envelope.fail("set", "issue-log", "INVALID_USAGE", "--step and --reason are required");
    }
    const reasonFail = validateReason(ctx.reason);
    if (reasonFail) return reasonFail;
    const optionalFields = [
      ["trigger", ctx.trigger],
      ["resolution", ctx.resolution],
      ["guardrail-candidate", ctx.guardrailCandidate],
    ];
    for (const [name, value] of optionalFields) {
      const fail = validateOptionalIssueLogField(name, value);
      if (fail) return fail;
    }
    const repairRef = normalizeRepairRef(ctx);
    const repairRefFail = validateRepairRef(repairRef);
    if (repairRefFail) return repairRefFail;

    const state = ctx.flowState;
    const taskId = resolveTaskIdForIssueLog(state, resolveExplicitTaskOption(ctx));

    const entry = {
      step: ctx.step,
      reason: ctx.reason,
      ...(ctx.trigger && { trigger: ctx.trigger }),
      ...(ctx.resolution && { resolution: ctx.resolution }),
      ...(ctx.guardrailCandidate && { guardrailCandidate: ctx.guardrailCandidate }),
      ...(ctx.normalizedFindingId && { normalizedFindingId: String(ctx.normalizedFindingId).trim() }),
      ...(repairRef && { repairRef }),
      taskId,
      timestamp: new Date().toISOString(),
    };

    const result = appendCanonicalIssueLogEntry(ctx.flowManager, state, entry);

    return { entry: result.entry, total: result.total };
  }
}

/**
 * src/flow/lib/set-issue.js
 *
 * Reject active-Flow Issue changes. Issue identity and issue.md are captured
 * together by canonical Flow creation and remain immutable afterwards.
 *
 * ctx.number — issue number (string or number)
 */

import { FlowCommand } from "./base-command.js";
import { Envelope } from "../../lib/flow-envelope.js";

export default class SetIssueCommand extends FlowCommand {
  execute(ctx) {
    const raw = ctx.number;

    if (raw == null || raw === "") {
      return Envelope.fail("set", "issue", "INVALID_USAGE", "usage: flow set issue <number>");
    }

    const str = String(raw);
    if (!/^\d+$/.test(str)) {
      return Envelope.fail(
        "set",
        "issue",
        "INVALID_ARG_VALUE",
        `not a valid positive integer: ${raw}`,
      );
    }

    const num = parseInt(str, 10);
    if (num < 1) {
      return Envelope.fail(
        "set",
        "issue",
        "INVALID_ARG_VALUE",
        `issue number must be a positive integer: ${raw}`,
      );
    }

    return Envelope.fail(
      "set",
      "issue",
      "ISSUE_IMMUTABLE",
      `linked Issue identity is immutable after canonical Flow creation (requested #${num})`,
    );
  }
}

/**
 * src/flow/lib/set-metric.js
 *
 * Append a metric entry to state.metrics (append-only array).
 *
 * ctx.phase   — one of VALID_PHASES (see constants.js)
 * ctx.counter — one of VALID_METRIC_COUNTERS (see constants.js)
 * ctx.taskId  — optional explicit taskId (overrides active-task inference)
 */

import { FlowCommand } from "./base-command.js";
import { VALID_PHASES, VALID_METRIC_COUNTERS } from "../../lib/constants.js";
import { Envelope } from "../../lib/flow-envelope.js";
import { resolveCommandRouteOptions } from "../../lib/flow-options.js";

export default class SetMetricCommand extends FlowCommand {
  execute(ctx) {
    const { phase, counter } = ctx;

    if (!phase || !counter) {
      return Envelope.fail(
        "set",
        "metric",
        "INVALID_USAGE",
        "usage: flow set metric <phase> <counter> [--task-id <id>]",
      );
    }

    if (!VALID_PHASES.includes(phase)) {
      return Envelope.fail(
        "set",
        "metric",
        "INVALID_PHASE",
        `invalid phase: ${phase} (valid: ${VALID_PHASES.join(", ")})`,
      );
    }

    if (!VALID_METRIC_COUNTERS.includes(counter)) {
      return Envelope.fail(
        "set",
        "metric",
        "INVALID_ARG_VALUE",
        `invalid counter: ${counter} (valid: ${VALID_METRIC_COUNTERS.join(", ")})`,
      );
    }

    ctx.flowManager.incrementMetric(phase, counter, resolveCommandRouteOptions(ctx));

    return { phase, counter };
  }
}

/**
 * src/flow/lib/set-note.js
 *
 * Append a note observation.
 *
 * Dual-mode operation (same pattern as set-auto.js):
 *   - Active Version-1 flow: append a typed note Activity. The command view
 *     derives state.notes from the Activity ledger.
 *   - Preparing flow (.active-flow.<runId>): mutate the preparing state so
 *     prelude choices are available to the prepare command input.
 *
 * ctx.text    — note text (required)
 * ctx.taskId  — optional explicit taskId (overrides active-task inference)
 * ctx.runId   — preparing-flow target (required in preparing mode)
 */

import { FlowCommand } from "./base-command.js";
import { Envelope } from "../../lib/flow-envelope.js";
import { resolveCommandRouteOptions } from "../../lib/flow-options.js";
import { resolvePreparingRunId } from "./resolve-preparing-run-id.js";

export default class SetNoteCommand extends FlowCommand {
  constructor() {
    super({ requiresFlow: false });
  }

  execute(ctx) {
    const { text } = ctx;

    if (!text) {
      return Envelope.fail(
        "set",
        "note",
        "INVALID_USAGE",
        'usage: flow set note "<text>" [--task-id <id>] [--run-id <id>]',
      );
    }

    const { flowManager, flowState } = ctx;
    const preparingMode = !flowState;

    if (preparingMode) {
      const resolved = resolvePreparingRunId(flowManager, ctx.runId, {
        type: "set",
        key: "note",
        zeroPreparingAsFail: true,
      });
      if (resolved.fail) return resolved.fail;

      flowManager.mutatePreparingFlow(resolved.runId, (s) => {
        if (!Array.isArray(s.notes)) s.notes = [];
        s.notes.push({ text, taskId: null, ts: new Date().toISOString() });
      });

      return { note: text, runId: resolved.runId };
    }

    ctx.flowManager.addNote(text, resolveCommandRouteOptions(ctx));
    return { note: text };
  }
}

import { FlowCommand } from "./base-command.js";
import {
  activateNonBlockingPolicy,
} from "./nonblocking.js";
import { nonblockingFailureEnvelope } from "./nonblocking-command-failure.js";
import { flowTargetBindingForContext } from "./guarded-command.js";

export default class SetPolicyCommand extends FlowCommand {
  execute(ctx) {
    if (ctx.value !== "nonblocking") throw new Error("usage: sennel flow set policy nonblocking --reason <text>");
    const binding = flowTargetBindingForContext(ctx);
    try {
      return activateNonBlockingPolicy({ root: ctx.root, flowManager: ctx.flowManager, reason: ctx.reason, binding });
    } catch (error) {
      return nonblockingFailureEnvelope({
        type: "set",
        key: "policy",
        error,
        state: ctx.flowState,
        binding,
      });
    }
  }
}

/**
 * src/flow/lib/set-request.js
 *
 * Set the user request field.
 *
 * The request is mutable only while a Flow is preparing.  Once the canonical
 * Version has been created it is an immutable identity/input fact.
 *
 * ctx.text  — request text
 * ctx.runId — preparing-flow target (required in preparing mode)
 */

import { FlowCommand } from "./base-command.js";
import { Envelope } from "../../lib/flow-envelope.js";
import { resolvePreparingRunId } from "./resolve-preparing-run-id.js";

export default class SetRequestCommand extends FlowCommand {
  constructor() {
    super({ requiresFlow: false });
  }

  execute(ctx) {
    const { text } = ctx;

    if (!text) {
      return Envelope.fail("set", "request", "INVALID_USAGE", 'usage: flow set request "<text>" [--run-id <id>]');
    }

    const { flowManager, flowState } = ctx;
    const preparingMode = !flowState;

    if (preparingMode) {
      const resolved = resolvePreparingRunId(flowManager, ctx.runId, {
        type: "set",
        key: "request",
        zeroPreparingAsFail: true,
      });
      if (resolved.fail) return resolved.fail;

      flowManager.mutatePreparingFlow(resolved.runId, (s) => {
        s.request = text;
      });
      return { request: text, runId: resolved.runId };
    }

    return Envelope.fail(
      "set",
      "request",
      "REQUEST_IMMUTABLE",
      "the active Flow request is immutable; use a preparing Flow before creation",
    );
  }
}

import { FlowCommand } from "./base-command.js";
import { Envelope } from "../../lib/flow-envelope.js";
import { findActiveNode, resolveMaxAttempts } from "../definition.js";
import { ReviewEvidenceInput } from "./review-evidence-store.js";
import {
  ReviewConvergenceState,
  ReviewEvidenceReference,
  buildReviewHandoffFindings,
  resolveReviewPermittedOperation,
} from "./review-convergence.js";
import { ReviewTargetAuthority } from "./review-target-authority.js";
import { isCanonicalFlowState } from "./canonical-test-artifacts.js";
import { FLOW_ARTIFACT_CONTRACTS } from "../../lib/flow-artifact-contract.js";

const PHASE_BY_REVIEW_STEP = Object.freeze({
  "draft-questions-review": "draft-questions",
  "draft-coverage-review": "draft-coverage",
  "spec-review": "spec",
  "test-review": "test",
  "impl-review": "impl",
  "task-review": "impl",
});

function currentReviewTarget(flowState, treeSha) {
  const active = findActiveNode(flowState);
  const phase = PHASE_BY_REVIEW_STEP[active?.stepId];
  if (!phase) {
    const error = new Error("review evidence can be registered only for the active review step");
    error.code = "REVIEW_TARGET_NOT_ACTIVE";
    throw error;
  }
  return {
    phase,
    taskId: active.scope === "task" ? active.taskId : null,
    treeSha,
    semanticMaxAttempts: resolveMaxAttempts({
      scope: active.scope,
      stepId: active.stepId,
      context: flowState,
    }),
  };
}

function canonicalReviewState({ evidence, target }) {
  const semanticAttempts = evidence.disposition.value === "REJECTED" ? 1 : 0;
  return new ReviewConvergenceState({
    phase: target.phase,
    taskId: target.taskId,
    treeSha: target.treeSha,
    semanticAttempts,
    semanticMaxAttempts: target.semanticMaxAttempts ?? 1,
    toolingAttempts: 0,
    toolingMaxAttempts: 1,
    evidence: new ReviewEvidenceReference({
      evidenceId: evidence.identity.evidenceDigest,
      disposition: evidence.disposition,
    }),
    finalizedEvidenceAvailable: true,
    handoffFindings: buildReviewHandoffFindings(evidence),
    blocker: null,
    toolingOutcome: null,
  });
}

function canonicalReviewNode(ctx, { phase, taskId }) {
  const activeNodeId = ctx.flowState.currentNodeId ?? null;
  const nodeId = taskId === null ? activeNodeId : "task-review";
  if (
    typeof nodeId !== "string"
    || PHASE_BY_REVIEW_STEP[nodeId] !== phase
    || (taskId === null ? nodeId === "task-review" : activeNodeId !== `${taskId}-review`)
  ) {
    const error = new Error("review evidence can be registered only for the active review step");
    error.code = "REVIEW_TARGET_NOT_ACTIVE";
    throw error;
  }
  return nodeId;
}

function assertCanonicalEvidenceIsNew(ctx, input) {
  const nodeId = canonicalReviewNode(ctx, input);
  const artifact = FLOW_ARTIFACT_CONTRACTS.reviewEvidence({
    ...(input.taskId === null ? { reviewStep: nodeId } : { taskId: input.taskId }),
    digest: input.evidence.identity.evidenceDigest,
  });
  const catalog = ctx.flowManager.artifactCatalog(ctx.flowState.specId);
  if (catalog.artifacts.some((entry) => entry.relativePath === artifact.relativePath)) {
    const error = new Error("review evidence is already registered for this target");
    error.code = "REVIEW_ALREADY_COMPLETED";
    throw error;
  }
}

function registerCanonicalReviewEvidence(ctx, { input, target }) {
  const evidence = input.toEvidence(target);
  const nodeId = canonicalReviewNode(ctx, target);
  const artifact = FLOW_ARTIFACT_CONTRACTS.reviewEvidence({
    ...(target.taskId === null ? { reviewStep: nodeId } : { taskId: target.taskId }),
    digest: evidence.identity.evidenceDigest,
  });
  ctx.flowManager.publishArtifacts({
    specId: ctx.flowState.specId,
    nodeId,
    artifactWrites: [{
      logicalKey: "review.evidence",
      ...(target.taskId === null ? { reviewStep: nodeId } : { taskId: target.taskId }),
      digest: evidence.identity.evidenceDigest,
      mediaType: "application/json",
      bytes: Buffer.from(`${evidence.canonicalText}\n`, "utf8"),
    }],
  });
  const convergenceState = canonicalReviewState({ evidence, target });
  return {
    providerInvoked: false,
    phase: target.phase,
    taskId: target.taskId,
    treeSha: target.treeSha,
    evidenceDigest: evidence.identity.evidenceDigest,
    artifactPath: artifact.relativePath,
    reviewAction: resolveReviewPermittedOperation(convergenceState).toJSON(),
  };
}

export default class SetReviewEvidenceCommand extends FlowCommand {
  execute(ctx) {
    if (typeof ctx.file !== "string" || ctx.file.trim() === "") {
      return Envelope.fail(
        "set",
        "review-evidence",
        "INVALID_USAGE",
        "usage: flow set review-evidence --file <path>",
      );
    }
    const canonical = isCanonicalFlowState(ctx.flowState);
    let input;
    let target;
    try {
      const authority = ReviewTargetAuthority.fromContext(ctx);
      input = ReviewEvidenceInput.fromFile({
        root: authority.executionRoot,
        // A Version directory is catalog-authoritative and cannot contain an
        // ad-hoc CLI source document.  The evidence file is read-only command
        // input, so V1 bounds it to the checked-out execution root instead.
        // The Store publishes only its normalized immutable bytes.
        specDir: authority.executionRoot,
        inputPath: ctx.file,
      });
      if (canonical) assertCanonicalEvidenceIsNew(ctx, input);
      target = currentReviewTarget(
        ctx.flowState,
        authority.resolveTreeSha(),
      );
      const fingerprint = authority.captureFingerprint();
      target.targetState = authority.captureTargetStateForPhase(target.phase, fingerprint);
      target.targetStateDigest = target.targetState.digest;
      input.validateTarget(target);
    } catch (error) {
      if (!error.code && /tree target mismatch/.test(error.message)) {
        error.code = "STALE_REVIEW_TARGET";
      } else if (!error.code) {
        error.code = "REVIEW_EVIDENCE_INVALID";
      }
      throw error;
    }

    if (!canonical) {
      throw new Error("review evidence registration requires a Version-1 Flow");
    }
    return registerCanonicalReviewEvidence(ctx, { input, target });
  }
}

import { CURRENT_FLOW_SCHEMA_REVISION } from "../../lib/flow-schema-revision.js";
/**
 * src/flow/lib/set-step.js
 *
 * Update a workflow step's status.
 * Side effects such as syncSpecTasks are driven by
 * the definition's sideEffects attribute — not hardcoded step IDs.
 */

import { FlowCommand } from "./base-command.js";
import { VALID_STEP_STATUSES } from "../../lib/constants.js";
import { container } from "../../lib/container.js";
import { Envelope } from "../../lib/flow-envelope.js";
import {
  findActiveNode,
  isDefinitionLifecycleOwnedStep,
  taskIdForResolvedStep,
} from "../definition.js";
import { findStepById } from "./step-tree.js";
import {
  NormalStepTransition,
  StepTransitionError,
} from "./step-transition-policy.js";
import { requiresWorkerArtifactHandoff } from "./flow-artifact-authority.js";
import { TaskStepIdentity } from "./task-step-identity.js";

function canonicalTargetId(activeNode, requestedId) {
  if (activeNode?.scope !== "task") return requestedId;
  if (["task-impl", "task-review", "task-triage", "task-repair", "task-gate"].includes(requestedId)) {
    return activeNode.stepId;
  }
  return requestedId;
}

export default class SetStepCommand extends FlowCommand {
  constructor() {
    super({ explicitTargetResolution: true });
  }

  async execute(ctx) {
    const { id, status } = ctx;

    if (!id || !status) {
      return Envelope.fail("set", "step", "INVALID_USAGE", "usage: flow set step <id> <status>");
    }

    if (!VALID_STEP_STATUSES.includes(status)) {
      return Envelope.fail(
        "set",
        "step",
        "INVALID_STATUS",
        `invalid status: ${status} (valid: ${VALID_STEP_STATUSES.join(", ")})`,
      );
    }

    if (
      status === "done"
      && requiresWorkerArtifactHandoff(id)
    ) {
      return Envelope.fail(
        "set",
        "step",
        "FLOW_ARTIFACT_HANDOFF_REQUIRED",
        `${id} completion is owned by the parent dispatcher artifact handoff`,
        {
          classification: "invalid",
          retryBudgetConsumed: false,
          completionOwner: "parent-dispatcher",
        },
      );
    }

    const state = ctx.flowManager.load();
    if (state?.schemaRevision !== CURRENT_FLOW_SCHEMA_REVISION) {
      return Envelope.fail("set", "step", "CANONICAL_FLOW_REQUIRED", "active Flow must be backed by the canonical Version Store");
    }
    const activeNode = state ? findActiveNode(state) : null;
    const activeScope = activeNode?.scope === "task"
      ? state.tasks?.find((task) => task.id === activeNode.taskId)
      : state;
    const targetId = canonicalTargetId(activeNode, id);
    const taskIdentity = TaskStepIdentity.fromStateNode(state, targetId);
    const storedStep = activeScope
      ? findStepById(activeScope.steps || [], targetId)
      : null;
    let transition;
    try {
      transition = new NormalStepTransition({
        stepId: targetId,
        currentStepId: activeNode?.stepId,
        currentStatus: storedStep?.status,
        requestedStatus: status,
        lifecycleOwned: isDefinitionLifecycleOwnedStep({
          scope: activeNode?.scope || "flow",
          stepId: id,
        }) || ["review", "triage", "repair", "gate"].includes(taskIdentity?.role),
      });
    } catch (error) {
      const transitionError = error instanceof StepTransitionError
        ? error
        : new StepTransitionError(error.message);
      return Envelope.fail("set", "step", transitionError.code, transitionError.message);
    }

    // Pass specId so the mutator can locate flow.json by path even when the
    // current flowManager root has no .active-flow entry for this spec
    // (spec 251: main-repo authority during finalize-merge / sync / cleanup).
    // The resolved active step owns its parent scope; a non-matching id is a
    // flow-level mutation rather than an implicit current-task lookup.
    ctx.flowManager.updateStepStatus(transition, {
      ...(ctx.specId ? { specId: ctx.specId } : {}),
      taskId: taskIdForResolvedStep(activeNode, targetId),
    });
    if (container.has("logger")) {
      container.get("logger").event("flow-step-change", { step: id, status });
    }

    return { id, status };
  }
}

