export const FLOW_QUERY_REQUEST_SCHEMAS = Object.freeze({
  metadata: Object.freeze({
    type: "object",
    required: ["resource", "condition"],
    properties: { resource: { type: "string", enum: ["metadata"] }, condition },
    additionalProperties: false,
  }),
  activities: Object.freeze({
    type: "object",
    required: ["resource", "condition", "page"],
    properties: { resource: { type: "string", enum: ["activities"] }, condition, page: page(FLOW_QUERY_LIMITS.MAX_PAGE_LIMIT), recordedAt },
    additionalProperties: false,
  }),
});

export const FLOW_QUERY_REQUEST_SCHEMA = Object.freeze({ oneOf: Object.values(FLOW_QUERY_REQUEST_SCHEMAS) });

function commonResponseProperties() {
  return {
    schemaRevision: { type: "integer", enum: [FLOW_QUERY_SCHEMA_REVISION] },
    ok: { type: "boolean" },
  };
}

const responsePageInfo = (allowNullLimit) => Object.freeze({
  type: "object",
  required: ["limit", "endCursor", "hasNext"],
  properties: {
    limit: allowNullLimit ? { type: ["integer", "null"], minimum: 1, maximum: FLOW_QUERY_LIMITS.MAX_PAGE_LIMIT } : positiveInteger(FLOW_QUERY_LIMITS.MAX_PAGE_LIMIT),
    endCursor: nullable(publicString),
    hasNext: { type: "boolean" },
  },
  additionalProperties: false,
});

function knownResponseProperties(resource, payload) {
  return {
    ...commonResponseProperties(),
    resource: { type: "string", enum: [resource] },
    selectedFlowVersion: { ...selectedFlowVersion, type: ["object", "null"] },
    availableFlowVersions,
    ...payload,
  };
}

const metadataSuccess = Object.freeze({
  type: "object",
  required: ["schemaRevision", "ok", "resource", "selectedFlowVersion", "availableFlowVersions", "item"],
  properties: knownResponseProperties("metadata", {
    ok: { type: "boolean", enum: [true] }, selectedFlowVersion, item: metadataItem,
  }),
  additionalProperties: false,
});

const activitiesSuccess = Object.freeze({
  type: "object",
  required: ["schemaRevision", "ok", "resource", "selectedFlowVersion", "availableFlowVersions", "items", "pageInfo"],
  properties: knownResponseProperties("activities", {
    ok: { type: "boolean", enum: [true] }, selectedFlowVersion, items: { type: "array", maxItems: FLOW_QUERY_LIMITS.MAX_PAGE_LIMIT, items: activityItem }, pageInfo: responsePageInfo(false),
  }),
  additionalProperties: false,
});

const metadataError = Object.freeze({
  type: "object",
  required: ["schemaRevision", "ok", "resource", "selectedFlowVersion", "availableFlowVersions", "error", "item"],
  properties: knownResponseProperties("metadata", {
    ok: { type: "boolean", enum: [false] }, error: queryError, item: { type: "null" },
  }),
  additionalProperties: false,
});

const activitiesError = Object.freeze({
  type: "object",
  required: ["schemaRevision", "ok", "resource", "selectedFlowVersion", "availableFlowVersions", "error", "items", "pageInfo"],
  properties: knownResponseProperties("activities", {
    ok: { type: "boolean", enum: [false] }, error: queryError, items: { type: "array", maxItems: 0 }, pageInfo: responsePageInfo(true),
  }),
  additionalProperties: false,
});

const unknownResourceError = Object.freeze({
  type: "object",
  required: ["schemaRevision", "ok", "error"],
  properties: { ...commonResponseProperties(), ok: { type: "boolean", enum: [false] }, error: queryError },
  additionalProperties: false,
});

export const FLOW_QUERY_RESPONSE_SCHEMA = Object.freeze({
  oneOf: [metadataSuccess, activitiesSuccess, metadataError, activitiesError, unknownResourceError],
});

function responseVariant(value) {
  if (value?.ok === true && value.resource === "metadata") return metadataSuccess;
  if (value?.ok === true && value.resource === "activities") return activitiesSuccess;
  if (value?.ok === false && value.resource === "metadata") return metadataError;
  if (value?.ok === false && value.resource === "activities") return activitiesError;
  if (value?.ok === false && !Object.hasOwn(value ?? {}, "resource")) return unknownResourceError;
  return FLOW_QUERY_RESPONSE_SCHEMA;
}

export function validateFlowQueryRequest(value) {
  const schema = FLOW_QUERY_REQUEST_SCHEMAS[value?.resource] ?? FLOW_QUERY_REQUEST_SCHEMA;
  return validateSchema(value, schema);
}

export function validateFlowQueryResponse(value) {
  const errors = validateSchema(value, responseVariant(value));
  if (errors.length > 0 || value?.ok !== false) return errors;
  const expectedPath = FLOW_QUERY_ERROR_PATHS[value.error?.code];
  if (expectedPath !== null && expectedPath !== undefined && value.error.path !== expectedPath) {
    errors.push(`error.path: must be ${expectedPath} for ${value.error.code}`);
  }
  return errors;
}

/**
 * tools/lib/cli.js
 *
 * repoRoot / parseArgs — 全エントリポイント共通の CLI ユーティリティ。
 */

import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";
import { runCmd, assertOk } from "./process.js";
import { PRODUCT } from "./product.js";

/**
 * sennel パッケージの src/ ディレクトリの絶対パス。
 * lib/ から1階層上が src/ であることを利用して解決する。
 */
export const PKG_DIR = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");

/**
 * 作業ルートを返す。
 * SENNEL_WORK_ROOT 環境変数が設定されている場合はそれを使用する（プロジェクトモード）。
 * それ以外は git rev-parse でリポジトリルートを取得し、失敗時は process.cwd() を返す。
 *
 * @returns {string} 作業ルートの絶対パス
 */
export function repoRoot() {
  if (process.env[PRODUCT.env("WORK_ROOT")]) return process.env[PRODUCT.env("WORK_ROOT")];
  // Logger 基盤の依存元のため runCmd を直接使う。runGit に変更してはならない
  // （Logger.git → resolveLogDir → repoRoot → runGit → Logger.git で無限再帰になる）。
  const res = runCmd("git", ["rev-parse", "--show-toplevel"]);
  if (res.ok) return res.stdout.trim();
  // npm パッケージとしてインストールされた場合、相対パス推定は
  // node_modules/ 内部を指すため process.cwd() を使用する
  return process.cwd();
}

/**
 * ソースルートを返す。
 * SENNEL_SOURCE_ROOT 環境変数が設定されている場合はそれを使用する（プロジェクトモード）。
 * それ以外は repoRoot() と同じ値を返す。
 *
 * @returns {string} ソースルートの絶対パス
 */
export function sourceRoot() {
  if (process.env[PRODUCT.env("SOURCE_ROOT")]) return process.env[PRODUCT.env("SOURCE_ROOT")];
  return repoRoot();
}

/**
 * 汎用 CLI パーサー。
 *
 * @param {string[]} argv - process.argv.slice(2)
 * @param {Object}   spec
 * @param {string[]} [spec.flags]    - ブール型フラグ (例: ["--dry-run","--force"])
 * @param {string[]} [spec.options]  - 値付きオプション (例: ["--type","--agent"])
 * @param {string[]} [spec.optionalOptions] - 任意の値を取るオプション (例: ["--reset"])
 * @param {Object}   [spec.aliases]  - 短縮名マップ (例: { "-v": "--verbose" })
 * @param {Object}   [spec.defaults] - デフォルト値
 * @returns {Object} パース済みオプション (help は常に含む)
 */
export function parseArgs(argv, spec) {
  const flags = new Set(spec.flags || []);
  const options = new Set(spec.options || []);
  const optionalOptions = new Set(spec.optionalOptions || []);
  const aliases = spec.aliases || {};
  const opts = { ...spec.defaults, help: false };

  for (let i = 0; i < argv.length; i += 1) {
    let a = argv[i];
    if (a === "--") continue;
    if (a in aliases) a = aliases[a];
    if (a === "-h" || a === "--help") { opts.help = true; continue; }
    if (flags.has(a)) {
      opts[flagKey(a)] = true;
      continue;
    }
    if (options.has(a)) {
      const value = argv[i + 1];
      if (value == null || String(value).trim() === "" || String(value).startsWith("-")) {
        throw new Error(`Missing value for option: ${a}`);
      }
      opts[flagKey(a)] = String(value).trim();
      i += 1;
      continue;
    }
    if (optionalOptions.has(a)) {
      const value = argv[i + 1];
      if (value != null && String(value).trim() !== "" && !String(value).startsWith("-")) {
        opts[flagKey(a)] = String(value).trim();
        i += 1;
      } else {
        opts[flagKey(a)] = true;
      }
      continue;
    }
    throw new Error(`Unknown option: ${a}`);
  }
  return opts;
}

/**
 * worktree 内で実行されているかを判定する。
 * git worktree では .git がディレクトリではなく `gitdir: ...` を含むファイルになる。
 *
 * @param {string} root - リポジトリルートパス
 * @returns {boolean}
 */
export function isInsideWorktree(root) {
  const dotGit = path.join(root, ".git");
  try {
    return fs.statSync(dotGit).isFile();
  } catch (_) {
    return false;
  }
}

/**
 * worktree からメインリポジトリのパスを取得する。
 * `git rev-parse --git-common-dir` で共有 .git ディレクトリを取得し、その親を返す。
 *
 * @param {string} root - リポジトリルートパス
 * @returns {string} メインリポジトリの絶対パス
 */
export function getMainRepoPath(root) {
  // Logger 基盤の依存元のため runCmd を直接使う。runGit に変更してはならない
  // （Logger.git → resolveLogDir → getMainRepoPath → runGit → Logger.git で無限再帰になる）。
  const res = runCmd("git", ["-C", root, "rev-parse", "--git-common-dir"]);
  if (!res.ok && !(res.status === 0 && res.stdout.trim())) {
    assertOk(res, "failed to resolve git-common-dir");
  }
  const gitCommonDir = res.stdout.trim();
  // git-common-dir は絶対パスまたは root からの相対パスを返す
  const abs = path.resolve(root, gitCommonDir);
  return path.dirname(abs);
}

/**
 * sennel パッケージのバージョン文字列を返す。
 * package.json の読み込みに失敗した場合は "?" を返す。
 *
 * @returns {string}
 */
export function getPackageVersion() {
  try {
    const pkg = JSON.parse(fs.readFileSync(path.join(PKG_DIR, "..", "package.json"), "utf8"));
    return pkg.version;
  } catch (_) {
    return "?";
  }
}

/**
 * UTC タイムスタンプ文字列を生成する。
 *
 * @param {Date} [date] - 日付オブジェクト（省略時は現在時刻）
 * @returns {string} "YYYY-MM-DD HH:MM:SS UTC"
 */
export function formatUTCTimestamp(date) {
  return (date || new Date()).toISOString().replace("T", " ").replace(/\.\d+Z$/, " UTC");
}

/** --some-flag → someFlag */
function flagKey(flag) {
  return flag.replace(/^--/, "").replace(/-([a-z])/g, (_, c) => c.toUpperCase());
}

/**
 * Unified command definitions for executable dispatch and import-safe help
 * metadata. Help reads never invoke lazy handlers, because command modules
 * may have import-time side effects.
 */

import { fileURLToPath, pathToFileURL } from "node:url";
import { FLOW_COMMANDS } from "../flow/registry.js";

const COMMAND_NAME_RE = /^[a-z0-9][a-z0-9-]*$/;

export class CommandHelpMetadata {
  constructor({
    name,
    section = "",
    summary = "",
    usage = "",
    help = "",
    args = {},
    options = [],
    experimental = false,
    localeKey = null,
    locale = null,
    owner = "core-command-metadata",
    subcommands = [],
  }) {
    if (typeof name !== "string" || name.trim() === "") {
      throw new Error("command help metadata requires a non-empty name");
    }
    this.name = name;
    this.section = section;
    this.summary = summary;
    this.usage = usage || `Usage: sennel ${name}`;
    this.help = help;
    this.args = args && typeof args === "object" ? args : {};
    this.options = Array.isArray(options) ? options : [];
    this.experimental = Boolean(experimental);
    this.localeKey = localeKey || null;
    this.locale = locale || null;
    this.owner = owner;
    this.subcommands = subcommands.map((entry) => entry instanceof CommandHelpMetadata
      ? entry
      : new CommandHelpMetadata({ ...entry, owner }));
  }

  find(parts) {
    const [head, ...rest] = parts;
    if (!head) return this;
    const sub = this.subcommands.find((entry) => (
      entry.name.split(" ").at(-1) === head || entry.name === [this.name, head].join(" ")
    ));
    return rest.length === 0 ? sub : sub?.find(rest);
  }

  all() {
    return [this, ...this.subcommands.flatMap((entry) => entry.all())];
  }
}

export class CoreCommandMetadataRegistry {
  constructor(entries) {
    this.entries = [];
    const names = new Set();
    for (const entry of entries) {
      const metadata = entry instanceof CommandHelpMetadata ? entry : new CommandHelpMetadata(entry);
      if (names.has(metadata.name)) throw new Error(`duplicate command help metadata: ${metadata.name}`);
      names.add(metadata.name);
      this.entries.push(metadata);
    }
  }

  findCommand(parts) {
    const normalized = Array.isArray(parts) ? parts : String(parts).split(/\s+/);
    const [head, ...rest] = normalized;
    const top = this.entries.find((entry) => entry.name === head);
    if (!top) return null;
    return rest.length === 0 ? top : top.find(rest);
  }

  topLevelCommands() {
    return this.entries.flatMap((entry) => entry.subcommands.length ? entry.subcommands : [entry]);
  }

  allCommands() {
    return this.entries.flatMap((entry) => entry.all());
  }
}

export class CommandEntrypoint {
  constructor({ modulePath, invocation }) {
    if (typeof modulePath !== "string" || modulePath.trim() === "") {
      throw new Error("command entrypoint modulePath is required");
    }
    if (!new Set(["main", "script"]).has(invocation)) {
      throw new Error(`invalid command entrypoint invocation: ${invocation}`);
    }
    this.moduleUrl = new URL(modulePath, import.meta.url);
    this.modulePath = fileURLToPath(this.moduleUrl);
    this.invocation = invocation;
    Object.freeze(this);
  }

  async execute(args) {
    process.argv = [process.argv[0], this.modulePath, ...args];
    const mod = await import(pathToFileURL(this.modulePath).href);
    if (this.invocation === "script") return;
    if (typeof mod.main !== "function") {
      throw new Error(`command module does not export main(): ${this.modulePath}`);
    }
    await mod.main();
  }
}

function helpText({ usage, summary, options = [] }) {
  const lines = [usage, "", summary];
  if (options.length > 0) {
    lines.push("", "Options:", ...options.map((option) => `  ${option}`));
  }
  return lines.join("\n");
}

export class CommandDefinition {
  constructor({
    name,
    command = null,
    outputMode = null,
    passthroughArgs = false,
    args = null,
    help = {},
    subcommands = [],
    entrypoint = null,
    dispatch = {},
    allowInvalidConfig = false,
    routed = false,
  }) {
    if (typeof name !== "string" || !COMMAND_NAME_RE.test(name)) {
      throw new Error(`invalid command name: ${name}`);
    }
    if (command != null && typeof command !== "function") {
      throw new Error(`command handler must be a function: ${name}`);
    }
    if (command && outputMode !== "raw" && outputMode !== "envelope") {
      throw new Error(`command outputMode is required: ${name}`);
    }
    this.name = name;
    this.command = command;
    this.outputMode = outputMode;
    this.passthroughArgs = Boolean(passthroughArgs);
    this.args = args;
    this.helpConfig = Object.freeze({ ...(typeof help === "string" ? {} : help) });
    this.help = typeof help === "string"
      ? help
      : typeof help.text === "string"
        ? help.text
        : helpText({
            usage: help.usage || `Usage: sennel ${name}`,
            summary: help.summary || "",
            options: help.options || [],
          });
    this.entrypoint = entrypoint instanceof CommandEntrypoint
      ? entrypoint
      : entrypoint
        ? new CommandEntrypoint(entrypoint)
        : null;
    this.allowInvalidConfig = Boolean(allowInvalidConfig);
    this.routed = Boolean(routed);
    Object.assign(this, dispatch);

    this.subcommands = new Map();
    for (const child of subcommands) {
      if (!(child instanceof CommandDefinition)) throw new Error(`invalid subcommand under ${name}`);
      if (this.subcommands.has(child.name)) throw new Error(`duplicate command: ${name} ${child.name}`);
      this.subcommands.set(child.name, child);
    }
    if (!this.command && !this.entrypoint && this.subcommands.size === 0 && !this.routed) {
      throw new Error(`command definition has no handler or subcommands: ${name}`);
    }
  }

  find(parts) {
    if (parts.length === 0) return this;
    const [head, ...rest] = parts;
    return this.subcommands.get(head)?.find(rest) || null;
  }

  metadata(parentPath = []) {
    const path = [...parentPath, this.name];
    return new CommandHelpMetadata({
      name: path.join(" "),
      section: this.helpConfig.section || "",
      summary: this.helpConfig.summary || "",
      usage: this.helpConfig.usage || this.help.split(/\r?\n/, 1)[0],
      help: this.help,
      args: this.args || {},
      options: this.helpConfig.options || [],
      experimental: Boolean(this.helpConfig.experimental),
      localeKey: this.helpConfig.localeKey || null,
      locale: this.helpConfig.locale || null,
      owner: this.helpConfig.owner || "core-command-metadata",
      subcommands: [...this.subcommands.values()].map((child) => child.metadata(path)),
    });
  }

  paths(parentPath = []) {
    const path = [...parentPath, this.name];
    return [path.join(" "), ...[...this.subcommands.values()].flatMap((child) => child.paths(path))];
  }

  renderHelp() {
    if (this.subcommands.size === 0) return this.help;
    const lines = [this.help, "", "Subcommands:"];
    for (const child of this.subcommands.values()) {
      lines.push(`  ${child.name.padEnd(14)}${child.helpConfig.summary || ""}`.trimEnd());
    }
    return lines.join("\n");
  }

  dispatchChildren() {
    return Object.fromEntries([...this.subcommands.values()].map((child) => [
      child.name,
      child.command || child.entrypoint ? child : child.dispatchChildren(),
    ]));
  }
}

export class CommandRegistry {
  constructor(definitions = []) {
    this.definitions = new Map();
    for (const definition of definitions) this.register(definition);
  }

  register(definition) {
    if (!(definition instanceof CommandDefinition)) throw new Error("CommandDefinition is required");
    if (this.definitions.has(definition.name)) throw new Error(`duplicate command: ${definition.name}`);
    this.definitions.set(definition.name, definition);
    return definition;
  }

  find(parts) {
    const normalized = Array.isArray(parts) ? parts : String(parts).trim().split(/\s+/);
    const [head, ...rest] = normalized;
    if (!head) return null;
    return this.definitions.get(head)?.find(rest) || null;
  }

  routePaths() {
    return [...this.definitions.values()].flatMap((definition) => definition.paths()).sort();
  }

  helpPaths() {
    return this.metadataRegistry().allCommands().map((entry) => entry.name).sort();
  }

  metadataRegistry() {
    return new CoreCommandMetadataRegistry(
      [...this.definitions.values()].map((definition) => definition.metadata()),
    );
  }
}

function rawDefinition(name, modulePath, help, { args = null, passthroughArgs = true } = {}) {
  return new CommandDefinition({
    name,
    command: () => import(modulePath),
    outputMode: "raw",
    passthroughArgs,
    args,
    help,
  });
}

