/**
 * Shared helpers for flow mutation option bags.
 */

/**
 * @typedef {Object} FlowRouteOptions
 * @property {string|null} [taskId] entry scope override; null writes flow scope
 * @property {string|null} [specId] flow.json target override; per-call beats bound defaults
 */

/**
 * @typedef {Object} AgentMetricPayloadOptions
 * @property {object} [usage]
 * @property {number} [responseChars]
 * @property {string} [model]
 * @property {number} [durationMs]
 * @property {string} [provider]
 * @property {string} [profileKey]
 */

/**
 * @typedef {FlowRouteOptions & AgentMetricPayloadOptions} AgentMetricOptions
 */

export function hasExplicitOption(opts, key) {
  return Boolean(opts) && Object.hasOwn(opts, key);
}

export function withSpecIdDefault(opts, specId) {
  if (hasExplicitOption(opts, "specId")) return opts;
  if (!specId) return opts;
  return { ...(opts || {}), specId };
}

export function withSpecIdArgDefault(specId, defaultSpecId) {
  return specId === undefined ? defaultSpecId ?? undefined : specId;
}

export function resolveExplicitTaskOption(ctx) {
  if (!hasExplicitOption(ctx, "taskId")) return undefined;
  const raw = ctx.taskId;
  return { taskId: raw === "" || raw == null ? null : raw };
}

export function resolveCommandRouteOptions(ctx) {
  return withSpecIdDefault(resolveExplicitTaskOption(ctx), ctx?.specId);
}

const FLOW_SPEC_ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]*$/;

export class FlowSpecId {
  constructor(value) {
    if (
      typeof value !== "string"
      || !FLOW_SPEC_ID_PATTERN.test(value)
      || value.includes("..")
      || value.endsWith(".")
      || value.endsWith(".lock")
    ) {
      throw new Error("flow spec ID must be a literal identifier");
    }
    this.value = value;
    Object.freeze(this);
  }

  static from(value) {
    return value instanceof FlowSpecId ? value : new FlowSpecId(value);
  }

  toString() {
    return this.value;
  }
}

import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import { FlowSpecId } from "./flow-spec-id.js";
import { Envelope } from "./flow-envelope.js";

const MAX_TARGET_TOKEN_LENGTH = 300;
const MAX_FLOW_TARGET_BINDING_TOKEN_BYTES = 32 * 1024;
const FLOW_TARGET_BINDING_VERSION = 2;
const FLOW_TARGET_BINDING_MODES = new Set(["branch", "direct", "worktree"]);

function normalizedToken(value, field) {
  if (value == null) return null;
  if (typeof value !== "string" || value.trim() === "" || value.length > MAX_TARGET_TOKEN_LENGTH) {
    throw new Error(`${field} must be a non-empty string up to ${MAX_TARGET_TOKEN_LENGTH} characters`);
  }
  return value.trim();
}

function normalizedIssue(value) {
  if (value == null) return null;
  const issue = Number(value);
  if (!Number.isSafeInteger(issue) || issue < 1) {
    throw new Error(`--expect-issue must be a positive integer: ${value}`);
  }
  return issue;
}

function normalizedSpec(value) {
  const token = normalizedToken(value, "--expect-spec");
  if (token == null) return null;
  try {
    return FlowSpecId.from(token).toString();
  } catch {
    throw new Error("--expect-spec must be a literal specId");
  }
}

function normalizedRunId(value) {
  return normalizedToken(value, "--expect-run-id");
}

function activeIssueOf(state) {
  return state?.issue == null ? null : Number(state.issue);
}

function activeSpecOf(state) {
  return state?.specId ?? null;
}

function activeRunIdOf(state) {
  return state?.runId || null;
}

function requireFlowState(input) {
  if (!input || typeof input !== "object" || Array.isArray(input)) {
    throw new Error("FlowTargetBinding requires active Flow state");
  }
  return input;
}

function canonicalDirectory(input, field) {
  if (typeof input !== "string" || !path.isAbsolute(input)) {
    throw new Error(`${field} must be an absolute directory`);
  }
  const resolved = path.resolve(input);
  let stat;
  let canonical;
  try {
    stat = fs.lstatSync(resolved);
    canonical = fs.realpathSync(resolved);
  } catch (cause) {
    throw new Error(`${field} is unavailable: ${resolved}`, { cause });
  }
  if (!stat.isDirectory() || stat.isSymbolicLink() || canonical !== resolved) {
    throw new Error(`${field} must be a canonical real directory: ${resolved}`);
  }
  return canonical;
}

function flowIssue(state) {
  const issue = state.issue ?? null;
  if (issue == null) return null;
  if (typeof issue !== "number" || !Number.isSafeInteger(issue) || issue < 1) {
    throw new Error("FlowTargetBinding issue must be a positive integer or null");
  }
  return issue;
}

function requireBranch(value, field) {
  if (typeof value !== "string" || value.trim() === "" || value.length > MAX_TARGET_TOKEN_LENGTH) {
    throw new Error(`FlowTargetBinding ${field} must be a non-empty branch name`);
  }
  return value.trim();
}

function flowAuthorityMode(flowState) {
  const mode = flowState?.execution?.mode;
  if (!FLOW_TARGET_BINDING_MODES.has(mode)) {
    throw new Error("FlowTargetBinding requires canonical execution.mode");
  }
  return mode;
}

class FlowExecutionAuthority {
  constructor(mode, mainRoot, executionRoot) {
    if (new.target === FlowExecutionAuthority) {
      throw new Error("FlowExecutionAuthority is abstract");
    }
    if (!FLOW_TARGET_BINDING_MODES.has(mode)) {
      throw new Error(`unsupported Flow target authority mode: ${mode}`);
    }
    this.mode = mode;
    this.mainRoot = canonicalDirectory(mainRoot, "FlowTargetBinding mainRoot");
    this.executionRoot = canonicalDirectory(executionRoot, "FlowTargetBinding executionRoot");
  }

  get dispatchLockRoot() {
    return this.mainRoot;
  }

  equals(other) {
    return other instanceof FlowExecutionAuthority
      && JSON.stringify(this.toJSON()) === JSON.stringify(other.toJSON());
  }

  static capture({ mode, flowState, mainRoot, authorityRoot, worktreePath }) {
    const activeMode = flowAuthorityMode(flowState);
    if (mode != null && mode !== activeMode) {
      throw new FlowTargetBindingMismatchError({
        expectedMode: mode ?? null,
        activeMode,
      });
    }
    if (activeMode === "worktree") {
      return new ManagedWorktreeFlowAuthority({
        mainRoot,
        executionRoot: authorityRoot,
        worktreePath: worktreePath ?? authorityRoot,
      });
    }
    if (activeMode === "branch" || activeMode === "direct") {
      return new BranchFlowAuthority({
        mode: activeMode,
        mainRoot,
        executionRoot: authorityRoot,
        featureBranch: flowState.featureBranch,
        baseBranch: flowState.baseBranch,
      });
    }
    throw new Error(`unsupported Flow target authority mode: ${activeMode}`);
  }

  static fromStored(value) {
    if (!value || typeof value !== "object" || Array.isArray(value)) {
      throw new Error("stored Flow target authority must be an object");
    }
    if (value.mode === "worktree") return new ManagedWorktreeFlowAuthority(value);
    if (value.mode === "branch" || value.mode === "direct") return new BranchFlowAuthority(value);
    throw new Error(`unsupported stored Flow target authority mode: ${value.mode}`);
  }
}

class BranchFlowAuthority extends FlowExecutionAuthority {
  constructor({ mode = "branch", mainRoot, executionRoot, featureBranch = null, baseBranch = null }) {
    super(mode, mainRoot, executionRoot);
    if (this.executionRoot !== this.mainRoot) {
      throw new Error(`${mode} Flow execution root must equal the canonical main repository`);
    }
    if (mode === "branch" && ((featureBranch === null) !== (baseBranch === null))) {
      throw new Error("FlowTargetBinding branch authority requires both branch names or neither");
    }
    if (mode === "direct" && featureBranch !== null) {
      throw new Error("FlowTargetBinding direct authority must not have a feature branch");
    }
    this.featureBranch = featureBranch === null ? null : requireBranch(featureBranch, "featureBranch");
    this.baseBranch = baseBranch === null ? null : requireBranch(baseBranch, "baseBranch");
    Object.freeze(this);
  }

  toJSON() {
    return {
      mode: this.mode,
      mainRoot: this.mainRoot,
      executionRoot: this.executionRoot,
      featureBranch: this.featureBranch,
      baseBranch: this.baseBranch,
    };
  }
}

class ManagedWorktreeFlowAuthority extends FlowExecutionAuthority {
  constructor({ mainRoot, executionRoot, worktreePath }) {
    super("worktree", mainRoot, executionRoot);
    this.worktreePath = canonicalDirectory(
      worktreePath,
      "FlowTargetBinding managed worktree path",
    );
    if (this.executionRoot !== this.worktreePath) {
      throw new Error("managed worktree execution root must equal the owned worktree path");
    }
    if (this.worktreePath === this.mainRoot) {
      throw new Error("managed worktree authority must differ from the main repository");
    }
    Object.freeze(this);
  }

  toJSON() {
    return {
      mode: this.mode,
      mainRoot: this.mainRoot,
      executionRoot: this.executionRoot,
      worktreePath: this.worktreePath,
    };
  }
}

export class FlowTargetBindingMismatchError extends Error {
  constructor(data) {
    super("active Flow authority no longer matches the captured FlowTargetBinding");
    this.name = "FlowTargetBindingMismatchError";
    this.code = "ACTIVE_FLOW_MISMATCH";
    this.data = Object.freeze({ ...data });
  }
}

function bindingMismatch(expected, active) {
  const mismatches = {};
  for (const [field, expectedKey, activeKey] of [
    ["runId", "expectedRunId", "activeRunId"],
    ["issue", "expectedIssue", "activeIssue"],
    ["specId", "expectedSpec", "activeSpec"],
  ]) {
    if (expected[field] !== active[field]) {
      mismatches[expectedKey] = expected[field];
      mismatches[activeKey] = active[field];
    }
  }
  const expectedAuthority = expected.authority;
  const activeAuthority = active.authority;
  for (const [field, label] of [
    ["mode", "Mode"],
    ["mainRoot", "MainRoot"],
    ["executionRoot", "ExecutionRoot"],
    ["worktreePath", "WorktreePath"],
    ["featureBranch", "FeatureBranch"],
    ["baseBranch", "BaseBranch"],
  ]) {
    const expectedValue = expectedAuthority[field] ?? null;
    const activeValue = activeAuthority[field] ?? null;
    if (expectedValue !== activeValue) {
      mismatches[`expected${label}`] = expectedValue;
      mismatches[`active${label}`] = activeValue;
    }
  }
  return mismatches;
}

export class FlowTargetBinding {
  constructor({ version = FLOW_TARGET_BINDING_VERSION, runId, issue, specId, authority }) {
    if (version !== FLOW_TARGET_BINDING_VERSION) {
      throw new Error(`unsupported FlowTargetBinding version: ${version}`);
    }
    this.version = version;
    this.runId = normalizedRunId(runId);
    if (this.runId == null) throw new Error("FlowTargetBinding runId is required");
    this.issue = flowIssue({ issue });
    this.specId = normalizedSpec(specId);
    if (this.specId == null) throw new Error("FlowTargetBinding specId is required");
    this.authority = authority instanceof FlowExecutionAuthority
      ? authority
      : FlowExecutionAuthority.fromStored(authority);
    Object.freeze(this);
  }

  static capture(input = {}) {
    const flowState = requireFlowState(input.flowState);
    return new FlowTargetBinding({
      runId: flowState.runId,
      issue: flowIssue(flowState),
      specId: flowState.specId,
      authority: FlowExecutionAuthority.capture({
        ...input,
        flowState,
      }),
    });
  }

  static captureContext(ctx, flowState = ctx?.flowState) {
    if (!ctx || typeof ctx !== "object" || Array.isArray(ctx)) {
      throw new Error("FlowTargetBinding context is required");
    }
    return FlowTargetBinding.capture({
      flowState,
      mainRoot: ctx.mainRoot || ctx.root,
      authorityRoot: ctx.executionRoot || ctx.root,
      worktreePath: flowState?.execution?.mode === "worktree" ? (ctx.executionRoot || ctx.root) : undefined,
    });
  }

  static deserialize(token) {
    if (typeof token !== "string" || token.trim() === "") {
      throw new Error("serialized FlowTargetBinding is required");
    }
    if (Buffer.byteLength(token) > MAX_FLOW_TARGET_BINDING_TOKEN_BYTES) {
      throw new Error(`serialized FlowTargetBinding must not exceed ${MAX_FLOW_TARGET_BINDING_TOKEN_BYTES} bytes`);
    }
    let value;
    try {
      value = JSON.parse(Buffer.from(token, "base64url").toString("utf8"));
    } catch (cause) {
      throw new Error("serialized FlowTargetBinding is invalid", { cause });
    }
    return new FlowTargetBinding(value);
  }

  get digest() {
    return crypto.createHash("sha256").update(JSON.stringify(this.toJSON())).digest("hex");
  }

  get dispatchLockRoot() {
    return this.authority.dispatchLockRoot;
  }

  serialize() {
    return Buffer.from(JSON.stringify(this.toJSON()), "utf8").toString("base64url");
  }

  guardCommand(command) {
    if (typeof command !== "string" || command.trim() === "") {
      throw new Error("FlowTargetBinding guarded command is required");
    }
    const issueGuard = this.issue == null
      ? " --expect-no-issue"
      : "";
    return `${command.trim()} --expect-binding '${this.serialize()}'${issueGuard}`;
  }

  mismatchAgainst(input) {
    let active;
    try {
      active = FlowTargetBinding.capture(input);
    } catch (error) {
      if (error?.code === "ACTIVE_FLOW_MISMATCH") throw error;
      throw new FlowTargetBindingMismatchError({
        expectedAuthority: this.authority.toJSON(),
        activeAuthorityInvalid: error?.message || String(error),
      });
    }
    const mismatches = bindingMismatch(this.toJSON(), active.toJSON());
    return Object.keys(mismatches).length === 0 ? null : mismatches;
  }

  assertCurrent(input) {
    const mismatch = this.mismatchAgainst(input);
    if (mismatch) throw new FlowTargetBindingMismatchError(mismatch);
    return this;
  }

  runIfCurrent(input, mutation) {
    if (typeof mutation !== "function") {
      throw new Error("FlowTargetBinding mutation callback is required");
    }
    this.assertCurrent(input);
    return mutation();
  }

  toJSON() {
    return {
      version: this.version,
      runId: this.runId,
      issue: this.issue,
      specId: this.specId,
      authority: this.authority.toJSON(),
    };
  }
}

export class FlowTargetExpectation {
  constructor(input = {}) {
    this.binding = input.expectBinding == null
      ? null
      : FlowTargetBinding.deserialize(input.expectBinding);
    this.issue = normalizedIssue(input.expectIssue);
    this.issueAbsent = input.expectNoIssue === true;
    if (this.issue != null && this.issueAbsent) {
      throw new Error("--expect-issue and --expect-no-issue cannot be used together");
    }
    this.specId = normalizedSpec(input.expectSpec);
    this.runId = normalizedRunId(input.expectRunId ?? input.expectRunID);
    if (this.binding) {
      const mismatch = this.mismatchAgainst(this.binding.toJSON());
      if (mismatch) {
        throw new Error("explicit target guards conflict with --expect-binding");
      }
    }
    Object.freeze(this);
  }

  get effectiveRunId() {
    return this.runId ?? this.binding?.runId ?? null;
  }

  get effectiveSpecId() {
    return this.specId ?? this.binding?.specId ?? null;
  }

  get effectiveIssue() {
    return this.issue ?? this.binding?.issue ?? null;
  }

  get expectsNoIssue() {
    return this.issueAbsent || (this.binding != null && this.binding.issue == null);
  }

  get empty() {
    return this.binding == null
      && this.issue == null
      && !this.issueAbsent
      && this.specId == null
      && this.runId == null;
  }

  mismatchAgainst(state) {
    if (this.empty || !state) return null;
    const mismatches = {};
    const expectedIssue = this.effectiveIssue;
    const expectsNoIssue = this.expectsNoIssue;
    const expectedSpec = this.effectiveSpecId;
    const expectedRunId = this.effectiveRunId;
    const activeIssue = activeIssueOf(state);
    const activeSpec = activeSpecOf(state);
    const activeRunId = activeRunIdOf(state);
    if (expectedIssue != null && activeIssue !== expectedIssue) {
      mismatches.expectedIssue = expectedIssue;
      mismatches.activeIssue = activeIssue;
    }
    if (expectsNoIssue && activeIssue !== null) {
      mismatches.expectedIssue = null;
      mismatches.activeIssue = activeIssue;
    }
    if (expectedSpec != null && activeSpec !== expectedSpec) {
      mismatches.expectedSpec = expectedSpec;
      mismatches.activeSpec = activeSpec;
    }
    if (expectedRunId != null && activeRunId !== expectedRunId) {
      mismatches.expectedRunId = expectedRunId;
      mismatches.activeRunId = activeRunId;
    }
    if (Object.keys(mismatches).length === 0) return null;
    return {
      ...mismatches,
      ...((expectedIssue != null || expectsNoIssue) && !("expectedIssue" in mismatches) && {
        expectedIssue,
        activeIssue,
      }),
      ...(expectedSpec != null && !("expectedSpec" in mismatches) && { expectedSpec, activeSpec }),
      ...(expectedRunId != null && !("expectedRunId" in mismatches) && { expectedRunId, activeRunId }),
    };
  }
}

function mismatchSummary(data) {
  if ("expectedIssue" in data && data.expectedIssue !== data.activeIssue) {
    if (data.expectedIssue == null) {
      return `Another flow is active for Issue #${data.activeIssue} but the specified target expects no Issue.`;
    }
    return `Another flow is active for Issue #${data.activeIssue ?? "none"} and does not match the specified #${data.expectedIssue}.`;
  }
  if ("expectedSpec" in data && data.expectedSpec !== data.activeSpec) {
    return `Another flow is active for spec ${data.activeSpec ?? "none"} and does not match the specified spec ${data.expectedSpec}.`;
  }
  if ("expectedRunId" in data && data.expectedRunId !== data.activeRunId) {
    return `Another flow is active for runId ${data.activeRunId ?? "none"} and does not match the specified runId ${data.expectedRunId}.`;
  }
  return "Another flow is active and does not match the specified target.";
}

export function buildTargetMismatchEnvelope({ type, key, data }) {
  const envelope = Envelope.fail(
    type,
    key,
    "ACTIVE_FLOW_MISMATCH",
    [
      mismatchSummary(data),
      "Stop before dispatching next-action, repair, run, finalize, or cleanup.",
    ],
    data,
  );
  envelope.errors[0].data = envelope.data;
  return envelope;
}

export function targetMismatchEnvelopeForInput({
  type,
  key,
  input,
  expectation: suppliedExpectation = null,
  flowState,
  mainRoot = null,
  authorityRoot = null,
  worktreePath = null,
  context = null,
}) {
  let expectation;
  try {
    expectation = suppliedExpectation ?? new FlowTargetExpectation(input);
    if (!(expectation instanceof FlowTargetExpectation)) {
      throw new Error("target expectation must be a FlowTargetExpectation");
    }
  } catch (err) {
    return Envelope.fail(type, key, "ARGS_ERROR", err.message);
  }
  if (expectation.binding) {
    if (context) {
      try {
        const active = FlowTargetBinding.captureContext(context, flowState);
        const data = bindingMismatch(expectation.binding.toJSON(), active.toJSON());
        if (Object.keys(data).length > 0) {
          return buildTargetMismatchEnvelope({ type, key, data });
        }
      } catch (err) {
        if (err?.code === "ACTIVE_FLOW_MISMATCH") {
          return buildTargetMismatchEnvelope({ type, key, data: err.data });
        }
        return buildTargetMismatchEnvelope({
          type,
          key,
          data: {
            expectedAuthority: expectation.binding.authority.toJSON(),
            activeAuthorityInvalid: err?.message || String(err),
          },
        });
      }
    } else {
    if (!flowState || !mainRoot || !authorityRoot) {
      return buildTargetMismatchEnvelope({
        type,
        key,
        data: {
          expectedRunId: expectation.binding.runId,
          activeRunId: activeRunIdOf(flowState),
        },
      });
    }
    try {
      expectation.binding.assertCurrent({
        flowState,
        mainRoot,
        authorityRoot,
        worktreePath: worktreePath ?? (flowState?.worktree === true ? authorityRoot : undefined),
      });
    } catch (err) {
      if (err?.code !== "ACTIVE_FLOW_MISMATCH") throw err;
      return buildTargetMismatchEnvelope({ type, key, data: err.data });
    }
    }
  }
  const data = expectation.mismatchAgainst(flowState);
  if (!data) return null;
  return buildTargetMismatchEnvelope({ type, key, data });
}

export function missingExactTargetGuardNames(input = {}, state = {}) {
  if (input.expectBinding != null) return [];
  const missing = [];
  if (input.expectRunId == null) missing.push("--expect-run-id");
  if (input.expectSpec == null) missing.push("--expect-spec");
  if (state.issue == null) {
    if (input.expectNoIssue !== true) missing.push("--expect-no-issue");
  } else if (input.expectIssue == null) {
    missing.push("--expect-issue");
  }
  return missing;
}

import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import { AtomicFile } from "./atomic-file.js";
import { AtomicJsonFile } from "./atomic-json-file.js";
import { managedDir } from "./config.js";
import { FlowSpecId } from "./flow-spec-id.js";
import { FlowVersion, FlowVersionRelativeLocation } from "./flow-version.js";
import { DEFAULT_FLOW_SPEC_DIR, FlowSpecRoot } from "./flow-workspace.js";
import { FileLock } from "./file-lock.js";
import { RealDirectoryAuthority } from "./real-directory-authority.js";
import { RepositoryFlowOperationLock, resolveRepositoryLockRoot } from "./repository-maintenance-lock.js";
import { PRODUCT } from "./product.js";

const AUTHORITY_FILE = ".flow-target-identities";
const AUTHORITY_LOCK_FILE = ".flow-target-identities.lock";
const AUTHORITY_REPOSITORY_PATHS = Object.freeze([
  PRODUCT.managedPath(AUTHORITY_FILE),
  PRODUCT.managedPath(AUTHORITY_LOCK_FILE),
]);
const PREPARING_PREFIX = ".active-flow.";
const ACTIVE_MODES = new Set(["worktree", "branch", "direct"]);
const LIFECYCLES = new Set(["preparing", "active"]);
const SAFE_RUN_ID = /^[A-Za-z0-9][A-Za-z0-9._-]*$/;
const MAX_RUN_ID_LENGTH = 200;

function authorityPath(mainRoot) {
  return path.join(managedDir(mainRoot), AUTHORITY_FILE);
}

function authorityRevision(bytes) {
  return bytes == null ? null : crypto.createHash("sha256").update(bytes).digest("hex");
}

function canonicalIdentityValue({ runId, issue, specId, lifecycle, mode, stateLocation }) {
  return JSON.stringify({ runId, issue, specId, lifecycle, mode, stateLocation });
}

function identityRevision(value) {
  return crypto.createHash("sha256").update(canonicalIdentityValue(value)).digest("hex");
}

function validIssue(value) {
  return value === null || (Number.isSafeInteger(value) && value > 0);
}

function validRepositoryRelativePath(value) {
  if (typeof value !== "string" || value === "" || value.includes("\\") || path.posix.isAbsolute(value)) {
    return false;
  }
  const normalized = path.posix.normalize(value);
  return normalized === value
    && value !== "."
    && value.split("/").every((segment) => segment !== "" && segment !== "." && segment !== "..");
}

function exactKeys(value, keys) {
  return value != null
    && typeof value === "object"
    && !Array.isArray(value)
    && JSON.stringify(Object.keys(value).sort()) === JSON.stringify([...keys].sort());
}

export class FlowTargetAuthorityError extends Error {
  constructor(message, { cause, data } = {}) {
    super(message, { cause });
    this.name = "FlowTargetAuthorityError";
    this.code = "FLOW_TARGET_AUTHORITY_CORRUPT";
    this.data = data;
  }
}

export class FlowTargetRecoveryError extends Error {
  constructor(identity, message, { cause, reason } = {}) {
    super(message, { cause });
    this.name = "FlowTargetRecoveryError";
    this.code = "FLOW_TARGET_RECOVERY_REQUIRED";
    this.data = {
      reason: reason ?? cause?.code ?? "FLOW_TARGET_STATE_INVALID",
      ...identity.toErrorData(),
    };
  }
}

export class FlowTargetIdentity {
  constructor({ runId, issue = null, specId = null, lifecycle, mode = null, stateLocation, revision = null } = {}) {
    if (
      typeof runId !== "string"
      || runId.length > MAX_RUN_ID_LENGTH
      || !SAFE_RUN_ID.test(runId)
      || runId === "."
      || runId === ".."
    ) {
      throw new FlowTargetAuthorityError("flow target identity runId is invalid");
    }
    const normalizedIssue = issue == null ? null : Number(issue);
    if (!validIssue(normalizedIssue)) {
      throw new FlowTargetAuthorityError(`flow target identity Issue is invalid for ${runId}`);
    }
    if (!LIFECYCLES.has(lifecycle)) {
      throw new FlowTargetAuthorityError(`flow target identity lifecycle is invalid for ${runId}`);
    }
    let normalizedSpecId = null;
    if (specId != null) {
      try {
        normalizedSpecId = FlowSpecId.from(specId).toString();
      } catch (cause) {
        throw new FlowTargetAuthorityError(`flow target identity specId is invalid for ${runId}`, { cause });
      }
    }
    if (lifecycle === "preparing" && (normalizedSpecId !== null || mode !== null)) {
      throw new FlowTargetAuthorityError(`preparing target identity must not have a spec or mode: ${runId}`);
    }
    if (lifecycle === "active" && (normalizedSpecId === null || !ACTIVE_MODES.has(mode))) {
      throw new FlowTargetAuthorityError(`active target identity requires a spec and mode: ${runId}`);
    }
    if (!validRepositoryRelativePath(stateLocation)) {
      throw new FlowTargetAuthorityError(`flow target identity state location is invalid for ${runId}`);
    }
    if (lifecycle === "active") {
      try {
        const location = FlowVersionRelativeLocation.fromArtifactPath({
          relativeArtifactPath: stateLocation,
          logicalKey: "flow.state",
        });
        if (location.specId.toString() !== normalizedSpecId) {
          throw new Error("active target location specId does not match its identity");
        }
      } catch (cause) {
        throw new FlowTargetAuthorityError(`active flow target state location is invalid for ${runId}`, { cause });
      }
    }
    const value = {
      runId,
      issue: normalizedIssue,
      specId: normalizedSpecId,
      lifecycle,
      mode,
      stateLocation,
    };
    const expectedRevision = identityRevision(value);
    if (revision != null && revision !== expectedRevision) {
      throw new FlowTargetAuthorityError(`flow target identity revision is stale for ${runId}`, {
        data: { runId, issue: normalizedIssue, specId: normalizedSpecId },
      });
    }
    this.runId = runId;
    this.issue = normalizedIssue;
    this.specId = normalizedSpecId;
    this.lifecycle = lifecycle;
    this.mode = mode;
    this.stateLocation = stateLocation;
    this.revision = expectedRevision;
    Object.freeze(this);
  }

  static fromStored(value) {
    if (!exactKeys(value, ["runId", "issue", "specId", "lifecycle", "mode", "stateLocation", "revision"])) {
      throw new FlowTargetAuthorityError("flow target identity entry has an invalid schema");
    }
    return new FlowTargetIdentity(value);
  }

  static preparing(state) {
    if (state?.lifecycle !== "preparing" || state?.specId !== null) {
      throw new FlowTargetAuthorityError("preparing flow state must retain preparing lifecycle and null specId");
    }
    return new FlowTargetIdentity({
      runId: state?.runId,
      issue: state?.issue ?? null,
      specId: null,
      lifecycle: "preparing",
      mode: null,
      stateLocation: PRODUCT.managedPath(`${PREPARING_PREFIX}${state?.runId}`),
    });
  }

  static active(state, mode, specRoot = DEFAULT_FLOW_SPEC_DIR) {
    const lifecycle = state?.lifecycle?.state ?? state?.lifecycle;
    if (lifecycle === "preparing") {
      throw new FlowTargetAuthorityError("active flow state must not use preparing lifecycle");
    }
    const executionMode = state?.execution?.mode;
    if (!ACTIVE_MODES.has(executionMode)) {
      throw new FlowTargetAuthorityError("active flow state requires a canonical execution mode");
    }
    if (mode !== executionMode) {
      throw new FlowTargetAuthorityError("active flow registry mode must match canonical execution mode");
    }
    const normalizedSpecId = FlowSpecId.from(state?.specId).toString();
    const versionLocation = new FlowVersionRelativeLocation({
      specRoot: FlowSpecRoot.from(specRoot).toString(),
      specId: normalizedSpecId,
      version: new FlowVersion(1),
    });
    return new FlowTargetIdentity({
      runId: state?.runId,
      issue: state?.issue ?? null,
      specId: normalizedSpecId,
      lifecycle: "active",
      mode,
      stateLocation: versionLocation.relativeArtifact("flow.state"),
    });
  }

  get preparing() {
    return this.lifecycle === "preparing";
  }

  matches(expectation) {
    return expectation.mismatchAgainst(this.toSelectionJSON()) == null;
  }

  assertState(state) {
    let actual;
    try {
      actual = this.preparing
        ? FlowTargetIdentity.preparing(state)
        : FlowTargetIdentity.active(
          state,
          this.mode,
          FlowVersionRelativeLocation.fromArtifactPath({
            relativeArtifactPath: this.stateLocation,
            logicalKey: "flow.state",
          }).specRoot,
        );
    } catch (cause) {
      throw new FlowTargetRecoveryError(
        this,
        `selected flow target state identity is invalid: ${this.runId}`,
        { cause, reason: "FLOW_TARGET_STATE_IDENTITY_INVALID" },
      );
    }
    if (actual.revision !== this.revision || actual.stateLocation !== this.stateLocation) {
      throw new FlowTargetRecoveryError(
        this,
        `selected flow target state does not match its identity authority: ${this.runId}`,
        { reason: "FLOW_TARGET_STATE_REVISION_MISMATCH" },
      );
    }
    return state;
  }

  toSelectionJSON() {
    return { runId: this.runId, issue: this.issue, specId: this.specId };
  }

  toErrorData() {
    return {
      runId: this.runId,
      issue: this.issue,
      specId: this.specId,
      lifecycle: this.lifecycle,
      mode: this.mode,
      stateLocation: this.stateLocation,
    };
  }

  toJSON() {
    return {
      ...this.toSelectionJSON(),
      lifecycle: this.lifecycle,
      mode: this.mode,
      stateLocation: this.stateLocation,
      revision: this.revision,
    };
  }
}

class FlowTargetIdentityDocument {
  constructor(entries = []) {
    if (!Array.isArray(entries)) {
      throw new FlowTargetAuthorityError("flow target identity authority must contain an array");
    }
    this.entries = entries.map((entry) => (
      entry instanceof FlowTargetIdentity ? entry : FlowTargetIdentity.fromStored(entry)
    ));
    const runIds = new Set();
    const activeSpecs = new Set();
    const locations = new Set();
    for (const entry of this.entries) {
      if (runIds.has(entry.runId)) {
        throw new FlowTargetAuthorityError(`flow target identity authority duplicates runId: ${entry.runId}`);
      }
      runIds.add(entry.runId);
      if (locations.has(entry.stateLocation)) {
        throw new FlowTargetAuthorityError(`flow target identity authority duplicates state location: ${entry.stateLocation}`);
      }
      locations.add(entry.stateLocation);
      if (entry.lifecycle === "active") {
        if (activeSpecs.has(entry.specId)) {
          throw new FlowTargetAuthorityError(`flow target identity authority duplicates specId: ${entry.specId}`);
        }
        activeSpecs.add(entry.specId);
      }
    }
  }

  findRunId(runId) {
    return this.entries.find((entry) => entry.runId === runId) ?? null;
  }

  findActiveSpec(specId) {
    return this.entries.find((entry) => entry.lifecycle === "active" && entry.specId === specId) ?? null;
  }

  addPreparing(state) {
    const next = FlowTargetIdentity.preparing(state);
    if (this.findRunId(next.runId)) {
      throw new FlowTargetAuthorityError(`flow target identity already exists: ${next.runId}`);
    }
    this.entries.push(next);
    return next;
  }

  addActive(state, mode, specRoot) {
    const next = FlowTargetIdentity.active(state, mode, specRoot);
    const sameRun = this.findRunId(next.runId);
    const sameSpec = this.findActiveSpec(next.specId);
    if (sameSpec && sameSpec.runId !== next.runId) {
      throw new FlowTargetAuthorityError(`active flow identity already exists for spec: ${next.specId}`);
    }
    if (sameRun && sameRun.lifecycle === "active" && sameRun.revision === next.revision) return sameRun;
    if (sameRun && sameRun.lifecycle !== "preparing") {
      throw new FlowTargetAuthorityError(`flow target runId conflicts during activation: ${next.runId}`);
    }
    this.entries = this.entries.filter((entry) => entry.runId !== next.runId && entry.specId !== next.specId);
    this.entries.push(next);
    return next;
  }

  replace(identity) {
    const index = this.entries.findIndex((entry) => entry.runId === identity.runId);
    if (index < 0) {
      throw new FlowTargetAuthorityError(`flow target identity is missing: ${identity.runId}`, {
        data: identity.toErrorData(),
      });
    }
    const current = this.entries[index];
    if (current.lifecycle !== identity.lifecycle || current.specId !== identity.specId || current.mode !== identity.mode) {
      throw new FlowTargetAuthorityError(`flow target identity replacement changes target ownership: ${identity.runId}`);
    }
    this.entries[index] = identity;
    return current;
  }

  remove({ runId = null, specId = null, lifecycle = null } = {}) {
    const matches = this.entries.filter((entry) => (
      (runId == null || entry.runId === runId)
      && (specId == null || entry.specId === specId)
      && (lifecycle == null || entry.lifecycle === lifecycle)
    ));
    if (matches.length > 1) {
      throw new FlowTargetAuthorityError("flow target identity removal is ambiguous");
    }
    if (matches.length === 0) return null;
    const selected = matches[0];
    this.entries = this.entries.filter((entry) => entry !== selected);
    return selected;
  }

  toJSON() {
    return this.entries.map((entry) => entry.toJSON());
  }
}

export class FlowTargetIdentitySnapshot {
  constructor({ entries, revision }) {
    this.entries = Object.freeze(entries.map((entry) => (
      entry instanceof FlowTargetIdentity ? entry : FlowTargetIdentity.fromStored(entry)
    )));
    if (revision != null && typeof revision !== "string") {
      throw new FlowTargetAuthorityError("flow target identity authority revision is invalid");
    }
    this.revision = revision;
    Object.freeze(this);
  }
}

function readAuthority(filePath) {
  try {
    fs.lstatSync(path.dirname(filePath));
  } catch (cause) {
    if (cause.code === "ENOENT") {
      return { document: new FlowTargetIdentityDocument(), revision: null };
    }
    throw new FlowTargetAuthorityError(`flow target identity authority is unreadable: ${filePath}`, { cause });
  }
  let bytes;
  try {
    bytes = new AtomicFile(filePath).read(null);
  } catch (cause) {
    throw new FlowTargetAuthorityError(`flow target identity authority is unreadable: ${filePath}`, { cause });
  }
  if (bytes == null) return { document: new FlowTargetIdentityDocument(), revision: null };
  let stored;
  try {
    stored = JSON.parse(bytes.toString("utf8"));
  } catch (cause) {
    throw new FlowTargetAuthorityError(`flow target identity authority is malformed: ${filePath}`, { cause });
  }
  return {
    document: new FlowTargetIdentityDocument(stored),
    revision: authorityRevision(bytes),
  };
}

export class FlowTargetIdentityAuthority {
  constructor({ mainRoot, specRoot = DEFAULT_FLOW_SPEC_DIR, processIdentitySource, faultInjector = () => {} } = {}) {
    this._mainRoot = resolveRepositoryLockRoot(mainRoot);
    this._specRoot = FlowSpecRoot.from(specRoot);
    this._processIdentitySource = processIdentitySource;
    this._faultInjector = faultInjector;
    const rootAuthority = new RealDirectoryAuthority(this._mainRoot);
    const directoryAuthority = new RealDirectoryAuthority(managedDir(this._mainRoot), {
      create: true,
      parentAuthority: rootAuthority,
    });
    this._lock = new FileLock({
      directoryAuthority,
      fileName: AUTHORITY_LOCK_FILE,
      kind: "flow-target-identity-authority",
      authority: { mainRoot: this._mainRoot, path: authorityPath(this._mainRoot) },
      ...(processIdentitySource && { processIdentitySource }),
      errorFactory: (status, message, { lockPath, cause } = {}) => {
        const error = new FlowTargetAuthorityError(message, { cause });
        error.code = status === "live" || status === "timeout"
          ? "FLOW_TARGET_AUTHORITY_BUSY"
          : `FLOW_TARGET_AUTHORITY_LOCK_${status.replace(/-/g, "_").toUpperCase()}`;
        error.lockPath = lockPath;
        return error;
      },
    });
  }

  static pathFor(mainRoot) {
    return authorityPath(resolveRepositoryLockRoot(mainRoot));
  }

  static managesRepositoryPath(filePath) {
    return AUTHORITY_REPOSITORY_PATHS.includes(filePath);
  }

  static repositoryPaths() {
    return AUTHORITY_REPOSITORY_PATHS;
  }

  snapshot() {
    const current = readAuthority(authorityPath(this._mainRoot));
    return new FlowTargetIdentitySnapshot({ entries: current.document.entries, revision: current.revision });
  }

  addPreparing(state, options = {}) {
    return this.#mutate((document) => document.addPreparing(state), options);
  }

  addActive(state, mode, options = {}) {
    return this.#mutate((document) => document.addActive(state, mode, this._specRoot), options);
  }

  replacePreparing(state, options = {}) {
    const identity = FlowTargetIdentity.preparing(state);
    return this.#mutate((document) => document.replace(identity), options);
  }

  replaceActive(state, mode, options = {}) {
    const identity = FlowTargetIdentity.active(state, mode, this._specRoot);
    return this.#mutate((document) => document.replace(identity), options);
  }

  removePreparing(runId, options = {}) {
    return this.#mutate((document) => document.remove({ runId, lifecycle: "preparing" }), options);
  }

  removeActive(specId, options = {}) {
    return this.#mutate((document) => document.remove({ specId, lifecycle: "active" }), options);
  }

  restore(identity, options = {}) {
    if (!(identity instanceof FlowTargetIdentity)) {
      throw new FlowTargetAuthorityError("restored flow target identity is invalid");
    }
    return this.#mutate((document) => {
      if (document.findRunId(identity.runId)) {
        throw new FlowTargetAuthorityError(`flow target identity already exists: ${identity.runId}`);
      }
      if (identity.lifecycle === "active" && document.findActiveSpec(identity.specId)) {
        throw new FlowTargetAuthorityError(`active flow identity already exists for spec: ${identity.specId}`);
      }
      if (document.entries.some((entry) => entry.stateLocation === identity.stateLocation)) {
        throw new FlowTargetAuthorityError(
          `flow target identity already exists for state location: ${identity.stateLocation}`,
        );
      }
      document.entries.push(identity);
      return identity;
    }, options);
  }

  #mutate(mutation, options) {
    const operationLock = new RepositoryFlowOperationLock({
      mainRoot: this._mainRoot,
      maintenanceOwnerToken: options.maintenanceOwnerToken ?? null,
      operationOwnerToken: options.operationOwnerToken ?? null,
      ...(this._processIdentitySource && { processIdentitySource: this._processIdentitySource }),
    });
    operationLock.acquire();
    let result;
    let primary = null;
    try {
      result = this._lock.runExclusive(() => {
        const current = readAuthority(authorityPath(this._mainRoot));
        const mutationResult = mutation(current.document);
        const fresh = readAuthority(authorityPath(this._mainRoot));
        if (fresh.revision !== current.revision) {
          const error = new FlowTargetAuthorityError("flow target identity authority changed concurrently");
          error.code = "FLOW_TARGET_AUTHORITY_REVISION_CONFLICT";
          throw error;
        }
        new AtomicJsonFile(authorityPath(this._mainRoot), { faultInjector: this._faultInjector })
          .write(current.document.toJSON());
        return mutationResult;
      });
    } catch (error) {
      primary = error;
    }
    let releaseError = null;
    try {
      operationLock.release();
    } catch (error) {
      releaseError = error;
    }
    if (primary && releaseError) {
      throw new AggregateError(
        [primary, releaseError],
        "flow target identity mutation and repository lock release both failed",
        { cause: primary },
      );
    }
    if (primary) throw primary;
    if (releaseError) throw releaseError;
    return result;
  }
}

const BASE_KEYS = Object.freeze(["runId", "lifecycle", "specId", "autoApprove"]);
const OPTIONAL_KEYS = Object.freeze([
  "issue",
  "issueBody",
  "request",
  "autoCheck",
  "autoDesired",
  "notes",
]);
const ALLOWED_KEYS = new Set([...BASE_KEYS, ...OPTIONAL_KEYS]);

function invariant(condition, message) {
  if (!condition) throw new PreparingFlowStateError(message);
}

function deepFreeze(value) {
  if (value === null || typeof value !== "object" || Object.isFrozen(value)) return value;
  Object.freeze(value);
  for (const child of Object.values(value)) deepFreeze(child);
  return value;
}

function exactKeys(value) {
  return Object.keys(value).every((key) => ALLOWED_KEYS.has(key))
    && BASE_KEYS.every((key) => Object.hasOwn(value, key));
}

function nonEmptyString(value, field) {
  invariant(typeof value === "string" && value.trim() !== "", `${field} must be a non-empty string`);
  return value;
}

function note(value, index) {
  invariant(value !== null && typeof value === "object" && !Array.isArray(value), `notes[${index}] must be an object`);
  invariant(
    Object.keys(value).length === 3
      && Object.hasOwn(value, "text")
      && Object.hasOwn(value, "taskId")
      && Object.hasOwn(value, "ts"),
    `notes[${index}] has an invalid schema`,
  );
  nonEmptyString(value.text, `notes[${index}].text`);
  invariant(value.taskId === null, `notes[${index}].taskId must be null while preparing`);
  invariant(Number.isFinite(Date.parse(value.ts)), `notes[${index}].ts must be an ISO timestamp`);
  return deepFreeze(structuredClone(value));
}

export class PreparingFlowStateError extends Error {
  constructor(message) {
    super(message);
    this.name = "PreparingFlowStateError";
    this.code = "PREPARING_FLOW_STATE_INVALID";
  }
}

/** Exact transient state persisted before a canonical Flow Version exists. */
export class PreparingFlowState {
  constructor(value) {
    invariant(value !== null && typeof value === "object" && !Array.isArray(value), "preparing flow state must be an object");
    invariant(exactKeys(value), "preparing flow state has an invalid schema");
    this.runId = nonEmptyString(value.runId, "preparing flow runId");
    invariant(value.lifecycle === "preparing", "preparing flow lifecycle must be preparing");
    invariant(value.specId === null, "preparing flow specId must be null");
    invariant(typeof value.autoApprove === "boolean", "preparing flow autoApprove must be boolean");
    this.lifecycle = "preparing";
    this.specId = null;
    this.autoApprove = value.autoApprove;

    if (Object.hasOwn(value, "issue")) {
      invariant(Number.isSafeInteger(value.issue) && value.issue > 0, "preparing flow issue must be a positive integer");
      this.issue = value.issue;
    }
    if (Object.hasOwn(value, "issueBody")) {
      invariant(Object.hasOwn(value, "issue"), "preparing flow issueBody requires an issue");
      this.issueBody = nonEmptyString(value.issueBody, "preparing flow issueBody");
    }
    if (Object.hasOwn(value, "request")) {
      this.request = nonEmptyString(value.request, "preparing flow request");
    }
    if (Object.hasOwn(value, "autoCheck")) {
      invariant(value.autoCheck !== null && typeof value.autoCheck === "object" && !Array.isArray(value.autoCheck), "preparing flow autoCheck must be an object");
      this.autoCheck = deepFreeze(structuredClone(value.autoCheck));
    }
    if (Object.hasOwn(value, "autoDesired")) {
      invariant(typeof value.autoDesired === "boolean", "preparing flow autoDesired must be boolean");
      this.autoDesired = value.autoDesired;
    }
    if (Object.hasOwn(value, "notes")) {
      invariant(Array.isArray(value.notes), "preparing flow notes must be an array");
      this.notes = Object.freeze(value.notes.map(note));
    }
    Object.freeze(this);
  }

  toJSON() {
    return structuredClone({
      runId: this.runId,
      lifecycle: this.lifecycle,
      specId: this.specId,
      autoApprove: this.autoApprove,
      ...(this.issue === undefined ? {} : { issue: this.issue }),
      ...(this.issueBody === undefined ? {} : { issueBody: this.issueBody }),
      ...(this.request === undefined ? {} : { request: this.request }),
      ...(this.autoCheck === undefined ? {} : { autoCheck: this.autoCheck }),
      ...(this.autoDesired === undefined ? {} : { autoDesired: this.autoDesired }),
      ...(this.notes === undefined ? {} : { notes: this.notes }),
    });
  }
}

/**
 * src/lib/preparing-flow-store.js
 *
 * Manages `.sennel/.active-flow.<runId>` — transient state files
 * created during the prepare phase before flow.json exists.
 */

import fs from "fs";
import path from "path";
import crypto from "crypto";
import { managedDir } from "./config.js";
import { AtomicFile } from "./atomic-file.js";
import { AtomicJsonFile } from "./atomic-json-file.js";
import { PreparingFlowState } from "./preparing-flow-state.js";
import { FileLock } from "./file-lock.js";
import { RealDirectoryAuthority } from "./real-directory-authority.js";
import {
  PREPARING_PREFIX,
  PREPARING_SCAN_LIMIT,
} from "./flow-helpers.js";

const MAX_RUN_ID_LENGTH = 200;
const SAFE_RUN_ID = /^[A-Za-z0-9][A-Za-z0-9._-]*$/;

class PreparingFlowId {
  constructor(value) {
    if (
      typeof value !== "string"
      || value.length > MAX_RUN_ID_LENGTH
      || !SAFE_RUN_ID.test(value)
      || value === "."
      || value === ".."
    ) {
      throw new Error("preparing flow runId must be a safe non-empty identifier");
    }
    this.value = value;
    Object.freeze(this);
  }

  toString() {
    return this.value;
  }

  lockName() {
    const digest = crypto.createHash("sha256").update(this.value).digest("hex");
    return `.preparing-flow.${digest}.lock`;
  }
}

class PreparingFlowSnapshot {
  constructor(filePath) {
    this.filePath = filePath;
    this.content = new AtomicFile(filePath).read(null);
    if (this.content == null) {
      const error = new Error(`preparing flow not found: ${path.basename(filePath)}`);
      error.code = "PREPARING_FLOW_NOT_FOUND";
      throw error;
    }
    this.revision = crypto.createHash("sha256").update(this.content).digest("hex");
    this.state = new PreparingFlowState(JSON.parse(this.content.toString("utf8"))).toJSON();
    Object.freeze(this);
  }

  assertCurrent() {
    const content = new AtomicFile(this.filePath).read(null);
    const revision = content == null
      ? null
      : crypto.createHash("sha256").update(content).digest("hex");
    if (revision !== this.revision || !content.equals(this.content)) {
      const error = new Error("preparing flow revision changed concurrently");
      error.code = "PREPARING_FLOW_REVISION_CONFLICT";
      throw error;
    }
  }
}

export class PreparingFlowStore {
  /**
   * @param {Object} opts
   * @param {string} opts.mainRoot
   */
  constructor({ mainRoot, faultInjector = () => {}, processIdentitySource } = {}) {
    this._mainRoot = path.resolve(mainRoot);
    this._faultInjector = faultInjector;
    this._processIdentitySource = processIdentitySource;
  }

  /** @returns {string} new runId */
  generateRunId() {
    return crypto.randomUUID();
  }

  /**
   * @param {string} runId
   * @param {object} [extra]
   * @returns {string} created file path
   */
  create(runId, extra = {}) {
    const id = new PreparingFlowId(runId);
    const state = {
      runId,
      lifecycle: "preparing",
      specId: null,
      autoApprove: false,
      ...extra,
    };
    if (state.runId !== runId || state.lifecycle !== "preparing" || state.specId !== null) {
      throw new Error("preparing flow state must preserve runId, preparing lifecycle, and null specId");
    }
    const p = this.#path(id);
    return this.#withLock(id, () => {
      if (fs.existsSync(p)) {
        const error = new Error(`preparing flow already exists: ${id}`);
        error.code = "PREPARING_FLOW_ALREADY_EXISTS";
        throw error;
      }
      const validState = new PreparingFlowState(state).toJSON();
      new AtomicJsonFile(p, { faultInjector: this._faultInjector }).write(validState);
      return p;
    });
  }

  /**
   * @param {string} runId
   * @returns {object|null}
   */
  load(runId) {
    const id = new PreparingFlowId(runId);
    const p = this.#path(id);
    if (!fs.existsSync(p)) return null;
    try {
      return new PreparingFlowSnapshot(p).state;
    } catch (cause) {
      const error = new Error(`preparing flow is corrupt: ${runId}`, { cause });
      error.code = "PREPARING_FLOW_CORRUPT";
      throw error;
    }
  }

  /**
   * Resolve { issue, request } from CLI args and a preparing-flow file.
   * CLI values take precedence; empty CLI values fall back to preparing values.
   *
   * @param {string} runId - runId from --run-id, or empty when absent
   * @param {string} cliIssue
   * @param {string} cliRequest
   * @returns {{ issue: string, request: string }}
   */
  resolveInputs(runId, cliIssue, cliRequest) {
    let issue = cliIssue || "";
    let request = cliRequest || "";
    if (!runId) return { issue, request };

    const preparing = this.load(runId);
    if (!preparing) {
      throw new Error(`preparing flow not found for runId: ${runId}`);
    }
    if (!issue && preparing.issue != null) issue = String(preparing.issue);
    if (!request && preparing.request) request = preparing.request;
    return { issue, request };
  }

  /**
   * Mutate a preparing flow state by runId. Loads the file, applies the
   * mutator, and writes it back atomically.
   *
   * @param {string} runId
   * @param {(state: object) => void} mutator
   * @returns {object} the updated state
   */
  mutate(runId, mutator) {
    const id = new PreparingFlowId(runId);
    const p = this.#path(id);
    return this.#withLock(id, () => {
      const snapshot = new PreparingFlowSnapshot(p);
      const state = structuredClone(snapshot.state);
      mutator(state);
      if (state.runId !== runId || state.lifecycle !== "preparing" || state.specId !== null) {
        throw new Error("preparing flow mutation must preserve runId, preparing lifecycle, and null specId");
      }
      const validState = new PreparingFlowState(state).toJSON();
      snapshot.assertCurrent();
      new AtomicJsonFile(p, { faultInjector: this._faultInjector }).write(validState);
      return validState;
    });
  }

  /** @param {string} runId */
  delete(runId) {
    const id = new PreparingFlowId(runId);
    const p = this.#path(id);
    if (!fs.existsSync(managedDir(this._mainRoot))) return;
    this.#withLock(id, () => {
      new AtomicFile(p, { faultInjector: this._faultInjector }).remove();
    });
  }

  /** @returns {string[]} runIds */
  list() {
    const dir = managedDir(this._mainRoot);
    if (!fs.existsSync(dir)) return [];
    return fs.readdirSync(dir)
      .filter((f) => f.startsWith(PREPARING_PREFIX))
      .map((f) => f.slice(PREPARING_PREFIX.length))
      .slice(0, PREPARING_SCAN_LIMIT);
  }

  #path(id) {
    return path.join(managedDir(this._mainRoot), `${PREPARING_PREFIX}${id}`);
  }

  #withLock(id, body) {
    const rootAuthority = new RealDirectoryAuthority(this._mainRoot);
    const directoryAuthority = new RealDirectoryAuthority(managedDir(this._mainRoot), {
      create: true,
      parentAuthority: rootAuthority,
    });
    const errorFactory = (status, message, { lockPath, cause } = {}) => {
      const error = new Error(message, { cause });
      error.code = status === "live" || status === "timeout"
        ? "PREPARING_FLOW_BUSY"
        : `PREPARING_FLOW_LOCK_${status.replace(/-/g, "_").toUpperCase()}`;
      error.lockPath = lockPath;
      return error;
    };
    const lock = new FileLock({
      directoryAuthority,
      fileName: id.lockName(),
      kind: "preparing-flow",
      authority: { mainRoot: this._mainRoot, runId: id.toString(), path: this.#path(id) },
      ...(this._processIdentitySource && { processIdentitySource: this._processIdentitySource }),
      errorFactory,
    });
    return lock.runExclusive(body);
  }

}
